// VANNE LYVA — état confirmé LoRaWAN + état officiel Node-RED
// Objectif : distinguer commande envoyée, commande en attente, état confirmé.

const cfg = Object.assign({ valveDevice: "lyva-tre" }, flow.get("config_jardin") || {});
const deviceId = msg.payload?.end_device_ids?.device_id;
if (deviceId !== cfg.valveDevice) return null;

const now = Date.now();
const uplink = msg.payload.uplink_message || {};
const decoded = uplink.decoded_payload || {};

let storedData = flow.get('vanne_lyva_state') || {
    state: "Fermé",
    battery: 100,
    last_seen_ts: null,
    state_confirmed_ts: null,
    timestamp: null
};

let valveState = flow.get('valve_state') || {
    device_id: deviceId,
    confirmed_state: storedData.state || "Fermé",
    status: "CLOSED_CONFIRMED",
    pending_command: null,
    pending_state: null,
    pending_since_ts: null,
    last_command_ts: null,
    last_confirmed_ts: storedData.state_confirmed_ts || null,
    last_seen_ts: storedData.last_seen_ts || null,
    battery: storedData.battery || 100,
    error: null
};

function normalizeState(s) {
    const x = String(s || "").toLowerCase();
    if (x.includes("ouvert") || x.includes("open")) return "Ouvert";
    if (x.includes("ferm") || x.includes("closed") || x.includes("close")) return "Fermé";
    return s || "Inconnu";
}
function statusFromState(s) {
    const n = normalizeState(s);
    if (n === "Ouvert") return "OPEN_CONFIRMED";
    if (n === "Fermé") return "CLOSED_CONFIRMED";
    return "UNKNOWN_CONFIRMED";
}
function pendingMatchesConfirmed(pendingState, confirmedState) {
    return normalizeState(pendingState) === normalizeState(confirmedState);
}

// Batterie
if (uplink.last_battery_percentage && uplink.last_battery_percentage.value !== undefined) {
    storedData.battery = Math.round(uplink.last_battery_percentage.value);
    valveState.battery = storedData.battery;
}

storedData.last_seen_ts = now;
storedData.timestamp = now;
valveState.last_seen_ts = now;
valveState.device_id = deviceId;

// État confirmé par l'uplink courant
if (decoded.result) {
    const confirmed = normalizeState(decoded.result);
    storedData.state = confirmed;
    storedData.state_confirmed_ts = now;

    valveState.confirmed_state = confirmed;
    valveState.last_confirmed_ts = now;
    valveState.status = statusFromState(confirmed);
    valveState.error = null;

    // Compatibilité avec l'ancien flow
    flow.set(`etat_${deviceId}`, confirmed);

    // Si une commande était en attente et que l'état confirmé correspond, on valide.
    if (valveState.pending_command && pendingMatchesConfirmed(valveState.pending_state, confirmed)) {
        node.warn(`[VANNE] Confirmation reçue : ${confirmed} — commande ${valveState.pending_command} validée`);
        valveState.pending_command = null;
        valveState.pending_state = null;
        valveState.pending_since_ts = null;
        flow.set(`commande_en_attente_${deviceId}`, null);
    }
}

flow.set('vanne_lyva_state', storedData);
flow.set('valve_state', valveState);

// Si la vanne est fermée pendant un arrosage, on remet l'orchestration au repos.
const arrosageState = flow.get('arrosage_state') || 'IDLE';
if (normalizeState(storedData.state) === "Fermé" && arrosageState === 'ARROSAGE') {
    flow.set('arrosage_state', 'IDLE');
    flow.set('arrosage_debut', null);
    flow.set('arrosage_duree_ms', 0);
    node.warn('[VANNE] Fermeture détectée pendant ARROSAGE — retour IDLE');
}

msg.payload = Object.assign({}, storedData, {
    valve_state: valveState,
    state: storedData.state,
    battery: storedData.battery
});
msg.topic = "vanne_state";
msg.auto_active = flow.get('auto_active') || false;
msg.maintenance_active = flow.get('maintenance_active') || false;
return msg;

// CHOIX VANNE — downlink port 10 + état pending/confirmed
// Compatible LoRaWAN : l'envoi ne vaut pas confirmation.

const cfg = Object.assign({
    appId: "jardin-version1",
    valveDevice: "lyva-tre",
    openHex: "01",
    closeHex: "02",
    commandTimeoutMin: 10
}, flow.get("config_jardin") || {});

const deviceId = msg.payload?.device_id || cfg.valveDevice;
const command = String(msg.payload?.command || "").toUpperCase();
const origin = msg.origin || msg.payload?.origin || "manual";

if (!/^[0-9A-F]{2}$/i.test(command)) {
    node.warn(`[CHOIX VANNE] Commande invalide : ${command}`);
    return null;
}

// Maintenance : on bloque seulement l'automatisme, pas les commandes manuelles.
if (flow.get("maintenance_active") === true && origin === "auto") {
    node.warn(`[CHOIX VANNE] Maintenance active — commande AUTO bloquée (${command})`);
    return null;
}

const now = Date.now();

// Sécurité énergie EcoFlow : on bloque toute ouverture quand la batterie est critique
// ou quand les données EcoFlow sont absentes/trop anciennes.
// Les commandes FERMER restent autorisées pour sécuriser l'installation.
const ecoLast = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");
const ecoAgeMin = ecoLast ? Math.round((now - Number(ecoLast)) / 60000) : null;
const ecoGuard = global.get("ecoflow_guard") === true; // sécurité EcoFlow réactivable depuis la page Réglages
const ecoStale = ecoGuard && (ecoAgeMin === null || ecoAgeMin > 15);
const ecoCutoff = ecoGuard && (global.get("energy_cutoff") === true || global.get("energie_ok") === false);
const ecoSoc = global.get("ecoflow_soc");
const isOpenCommand = command === cfg.openHex;
const isCloseCommand = command === cfg.closeHex;

if (ecoCutoff || ecoStale) {
    if (flow.get("auto_active") === true) flow.set("auto_before_cutoff", true);
    flow.set("auto_active", false);
    flow.set("pending_config_lent", false);
    if ((flow.get("arrosage_state") || "IDLE") !== "IDLE") {
        flow.set("arrosage_state", "IDLE");
        flow.set("arrosage_debut", null);
        flow.set("arrosage_duree_ms", 0);
        flow.set("arrosage_fin_ts", null);
    }
}

if (isOpenCommand && (ecoCutoff || ecoStale)) {
    node.warn(`[CHOIX VANNE] OUVERTURE BLOQUÉE — EcoFlow ${ecoCutoff ? "en coupure" : "donnée absente/trop ancienne"} | SOC=${ecoSoc ?? "--"}% | âge=${ecoAgeMin ?? "--"}min`);
    return null;
}

// En coupure, on ne laisse passer que la fermeture.
if (!isCloseCommand && (ecoCutoff || ecoStale)) {
    node.warn(`[CHOIX VANNE] Commande bloquée par sécurité EcoFlow (${command})`);
    return null;
}

const desiredState = command === cfg.openHex ? "Ouvert" : (command === cfg.closeHex ? "Fermé" : null);
let valveState = flow.get('valve_state') || {
    device_id: deviceId,
    confirmed_state: "Inconnu",
    status: "UNKNOWN",
    pending_command: null,
    pending_state: null,
    pending_since_ts: null,
    last_command_ts: null,
    last_confirmed_ts: null,
    last_seen_ts: null,
    battery: null,
    error: null
};

function norm(s) {
    const x = String(s || "").toLowerCase();
    if (x.includes("ouvert") || x.includes("open")) return "Ouvert";
    if (x.includes("ferm") || x.includes("closed") || x.includes("close")) return "Fermé";
    return s || "Inconnu";
}

const confirmed = norm(valveState.confirmed_state || flow.get(`etat_${deviceId}`));

// Si la commande est déjà confirmée et aucune commande n'est en attente, inutile de renvoyer.
if (desiredState && !valveState.pending_command && confirmed === desiredState) {
    node.warn(`[CHOIX VANNE] Commande ignorée pour ${deviceId} : déjà confirmé ${confirmed}`);
    return null;
}

// Si même commande déjà en attente, relance autorisée sans remettre à zéro pending_since_ts.
if (valveState.pending_command === command) {
    node.warn(`[CHOIX VANNE] Relance autorisée pour ${deviceId} — commande déjà en attente depuis ${Math.round((now - (valveState.pending_since_ts || now))/60000)}min`);
} else {
    valveState.pending_command = command;
    valveState.pending_state = desiredState;
    valveState.pending_since_ts = now;
    valveState.status = desiredState === "Ouvert" ? "OPEN_PENDING" : (desiredState === "Fermé" ? "CLOSE_PENDING" : "CONFIG_PENDING");
    valveState.error = null;
    flow.set(`commande_en_attente_${deviceId}`, command);
    node.warn(`[CHOIX VANNE] Nouvelle commande pour ${deviceId} : ${command} → ${desiredState || 'config'}`);
}

valveState.device_id = deviceId;
valveState.last_command_ts = now;
valveState.pending_origin = origin;
flow.set('valve_state', valveState);

const base64 = Buffer.from(command, 'hex').toString('base64');
msg.topic = `v3/${cfg.appId}@ttn/devices/${deviceId}/down/push`;
msg.payload = {
  downlinks: [
    {
      frm_payload: base64,
      f_port: 10,
      priority: "NORMAL"
    }
  ]
};
return msg;

const cfg = Object.assign({ appId: "jardin-version1", valveDevice: "lyva-tre" }, flow.get("config_jardin") || {});
const deviceId = msg.payload?.device_id || cfg.valveDevice;
const hexCmd = String(msg.payload?.command || "").toUpperCase();
const origin = msg.origin || msg.payload?.origin || "manual";

if (flow.get("maintenance_active") === true && origin === "auto") {
    node.warn(`[CONFIG VANNE] Maintenance active — config AUTO bloquée (${hexCmd})`);
    return null;
}

if (!/^[0-9A-Fa-f]{2}$/.test(hexCmd)) {
    node.warn("Commande hex invalide : " + hexCmd);
    return null;
}

// Sécurité énergie EcoFlow : aucune configuration de réveil quand la batterie est en coupure.
// Cela évite de réveiller/envoyer des downlinks inutiles pendant l'attente recharge.
const ecoLast = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");
const ecoAgeMin = ecoLast ? Math.round((Date.now() - Number(ecoLast)) / 60000) : null;
const ecoGuard = global.get("ecoflow_guard") === true; // sécurité EcoFlow réactivable depuis la page Réglages
const ecoStale = ecoGuard && (ecoAgeMin === null || ecoAgeMin > 15);
const ecoCutoff = ecoGuard && (global.get("energy_cutoff") === true || global.get("energie_ok") === false);

if (ecoCutoff || ecoStale) {
    node.warn(`[CONFIG VANNE] Config bloquée par sécurité EcoFlow | coupure=${ecoCutoff} | âge=${ecoAgeMin ?? "--"}min`);
    return null;
}

const base64 = Buffer.from(hexCmd, "hex").toString("base64");
msg.topic = `v3/${cfg.appId}@ttn/devices/${deviceId}/down/push`;
msg.payload = {
  downlinks: [{
    frm_payload: base64,
    f_port: 11,
    priority: "NORMAL"
  }]
};

node.warn("Envoi port 11 : " + hexCmd + " pour " + deviceId);
return msg;

// Vérifie si le message vient du port 11
const uplink = msg.payload?.data?.uplink_message || msg.payload?.uplink_message;
if (!uplink || uplink.f_port !== 11 || !uplink.frm_payload) return null;

// Décode le byte : 0x02 = 2min, 0x1E = 30min
const byte = Buffer.from(uplink.frm_payload, 'base64')[0];
const mode = (byte === 0x02) ? 2 : 30;

flow.set('vanne_current_mode', mode);
node.warn(`[MODE] f_port 11 → ${mode}min`);

msg.payload = { mode: mode };
msg.auto_active = flow.get('auto_active') === true;
msg.maintenance_active = flow.get('maintenance_active') === true;
return msg;

// --- 1. RECUPERATION RACINE ---
let root = msg.payload;
if (root.data && root.data.uplink_message) {
    root = root.data;
}

// --- 2. VERIF ID ---
let deviceId = root.end_device_ids?.device_id || msg.payload.end_device_ids?.device_id;
if (deviceId !== "debitmetre") return null;

const uplink = root.uplink_message;
if (!uplink) return null;

// --- 3. EXTRACTION BATTERIE ---
// On la stocke dans msg.battery pour la passer au noeud suivant
let battery = 100; // Valeur par défaut
if (uplink.last_battery_percentage?.value !== undefined) {
    battery = uplink.last_battery_percentage.value;
} else if (uplink.decoded_payload?.battery !== undefined) {
    battery = uplink.decoded_payload.battery;
}
// On attache la batterie au message global
msg.battery = Math.round(parseFloat(battery));

// --- 4. DECODAGE VOLUME (LITRES) ---
let volumeLitres = null;

// A. Via Décodeur TTN (Facile)
if (uplink.decoded_payload && uplink.decoded_payload.debit !== undefined) {
    let val = uplink.decoded_payload.debit;
    if (uplink.decoded_payload.unit === "m³" || uplink.decoded_payload.unit === "m3") {
        volumeLitres = val * 1000;
    } else {
        volumeLitres = val;
    }
}

// B. Via Décodage Manuel (Secours "AAAl3w==")
if (volumeLitres === null && uplink.frm_payload) {
    try {
        let buffer = Buffer.from(uplink.frm_payload, 'base64');
        // Lecture Big Endian 32 bits (ex: 9695)
        volumeLitres = buffer.readUInt32BE(0);
    } catch (e) {
        node.warn("Echec décodage manuel");
    }
}

// --- 5. SORTIE ---
if (volumeLitres !== null) {
    // On envoie juste le nombre de litres dans le payload
    // La batterie est stockée dans msg.battery
    msg.payload = volumeLitres;
    return msg;
}

return null;

// DÉBITMÈTRE — litres du jour + quota journalier AUTO
// Quota par défaut : 200 L.
// Si quota atteint : blocage de l'arrosage AUTO jusqu'à reset journalier ou reset manuel.
// Le mode MANUEL reste autorisé car ce blocage est appliqué uniquement dans la logique IA/AUTO.

function localDayKey(d = new Date()) {
  // Jour calendaire dans le fuseau du jardin (indépendant du fuseau du serveur)
  return d.toLocaleDateString('en-CA', { timeZone: TZJARDIN });
}

const cfg = Object.assign({ dailyWaterQuotaL: 200 }, flow.get("config_jardin") || {});
const TZJARDIN = cfg.timezone || "Europe/Paris";
const quotaL = Number(cfg.dailyWaterQuotaL || 200);

const now = new Date();
const dayKeyNow = localDayKey(now);
const resetRequestTs = flow.get("water_quota_reset_request_ts") || null;

let st = context.get('st') || {
  dayKey: dayKeyNow,
  dayStartTotalL: null,
  lastTotalL: null,
  todayLiters: 0,
  lastUpdateTS: Date.now(),
  lastResetRequestTs: null
};

// --- TRAITEMENT DONNÉES ---
let currentTotalL = null;
let battery = 100;

if (typeof msg.payload === 'number') {
  currentTotalL = msg.payload;
  st.lastUpdateTS = Date.now();
}

if (msg.battery !== undefined) battery = Math.round(parseFloat(msg.battery));
if (currentTotalL === null) return null;

// --- RESET QUOTIDIEN OU RESET MANUEL ---
// Reset journalier : nouveau compteur à partir de l'index total actuel.
// Reset manuel : utilisé par le bouton Reset d'urgence, appliqué au prochain uplink débitmètre.
const manualResetRequested = resetRequestTs && resetRequestTs !== st.lastResetRequestTs;

if (msg.reset === true || st.dayKey !== dayKeyNow || manualResetRequested) {
  st.dayKey = dayKeyNow;
  st.dayStartTotalL = currentTotalL;
  st.todayLiters = 0;
  st.lastResetRequestTs = resetRequestTs;
}

// --- INITIALISATION ---
if (st.dayStartTotalL === null) {
  st.dayStartTotalL = currentTotalL;
  st.lastTotalL = currentTotalL;
}

// --- CALCULS ---
let todayL = currentTotalL - st.dayStartTotalL;
if (todayL < 0) todayL = 0;

const consumedRounded = Math.round(todayL);
const remainingL = Math.max(0, quotaL - consumedRounded);
const quotaReached = consumedRounded >= quotaL;

// Sauvegarde locale et flow global
st.lastTotalL = currentTotalL;
st.todayLiters = todayL;
context.set('st', st);

const quotaState = {
  dayKey: st.dayKey,
  consumed: consumedRounded,
  quota: quotaL,
  remaining: remainingL,
  reached: quotaReached,
  percent: quotaL > 0 ? Math.min(100, Math.round((consumedRounded / quotaL) * 100)) : 0,
  total_index: currentTotalL,
  battery,
  timestamp: st.lastUpdateTS,
  lastResetRequestTs: st.lastResetRequestTs
};
flow.set("water_quota_state", quotaState);

node.status({
  fill: quotaReached ? "red" : "green",
  shape: quotaReached ? "ring" : "dot",
  text: `Jour: ${consumedRounded}/${quotaL} L | Restant: ${remainingL} L | Bat: ${battery}%`
});

// --- SORTIE DASHBOARD ---
msg.payload = {
  consumed: consumedRounded,
  total_index: currentTotalL,
  battery,
  target: quotaL,
  quota: quotaL,
  remaining: remainingL,
  quota_reached: quotaReached,
  quota_percent: quotaState.percent,
  timestamp: st.lastUpdateTS
};

return msg;

// CHEF D'ORCHESTRE — Exécuté à CHAQUE réveil de la vanne LYVA

const KEY_TARGET    = "vanne_target_timestamp";
const KEY_MODE      = "vanne_current_mode";
const KEY_BAT       = "vanne_battery_level";
const KEY_LAST_CMD  = "orchestre_last_cmd_ts";   // Cooldown anti-rafale
const cfg = Object.assign({ valveDevice: "lyva-tre", openHex: "01", closeHex: "02", slowModeHex: "1E", commandCooldownMs: 10000 }, flow.get("config_jardin") || {});
const COOLDOWN_MS   = cfg.commandCooldownMs;     // cooldown anti-rafale

let currentMode = flow.get(KEY_MODE) || 30;
let battery     = flow.get(KEY_BAT)  || 100;

if (msg.payload?.battery != null) battery = msg.payload.battery;
flow.set(KEY_BAT, battery);

const now        = Date.now();
const targetTime = now + (currentMode * 60 * 1000);
flow.set(KEY_TARGET, targetTime);

const state    = flow.get('arrosage_state')   || 'IDLE';
const deviceId = flow.get('arrosage_device')  || cfg.valveDevice;
const dureeMs  = flow.get('arrosage_duree_ms') || 0;
let   debut    = flow.get('arrosage_debut');
const etatVanne = msg.payload?.state || msg.payload?.valve_state?.confirmed_state || "";

if (flow.get("maintenance_active") === true && state !== 'IDLE') {
    flow.set('arrosage_state', 'IDLE');
    flow.set('arrosage_debut', null);
    flow.set('arrosage_duree_ms', 0);
    flow.set('pending_config_lent', false);
    node.warn('[ORCHESTRE] Maintenance active — automatisme arrêté');
    return [msg, null];
}

// ── Sécurité : reset si état bloqué > 2h sans commande ──
if (state !== 'IDLE') {
    const sinceLastSec = (now - (flow.get(KEY_LAST_CMD) || 0)) / 1000;
    if (sinceLastSec > 7200) {
        node.warn(`[ORCHESTRE] ⚠️ État "${state}" bloqué ${Math.round(sinceLastSec/60)}min → RESET IDLE`);
        flow.set('arrosage_state', 'IDLE');
        flow.set('arrosage_debut', null);
        flow.set('arrosage_duree_ms', 0);
        flow.set('pending_config_lent', false);
    }
}

node.warn(`[ORCHESTRE] État: ${state} | Vanne: "${etatVanne}" | Mode: ${currentMode}min`);

// GARDE COOLDOWN — empêche les rafales de commandes
const lastCmdTs  = flow.get(KEY_LAST_CMD) || 0;
const sinceLastCmd = now - lastCmdTs;

function sendCmd(cmdMsg) {
    // Enregistre le timestamp avant d'envoyer
    flow.set(KEY_LAST_CMD, now);
    return cmdMsg;
}

function cooldownOk(label) {
    if (sinceLastCmd < COOLDOWN_MS) {
        node.warn(`[ORCHESTRE] ⏳ COOLDOWN (${Math.round(sinceLastCmd/1000)}s < ${COOLDOWN_MS/1000}s) → ${label} différé au prochain réveil`);
        return false;
    }
    return true;
}

// TRANSITIONS D'ÉTAT

if (state === 'PREP_RAPIDE') {
    flow.set('arrosage_state', 'ATTENTE_OUVERTURE');
    node.warn('[ORCHESTRE] PREP_RAPIDE → envoi OUVRIR');
    return [msg, sendCmd({ topic: "valve", origin: "auto", payload: { device_id: deviceId, command: cfg.openHex, origin: "auto" } })];
}

if (state === 'ATTENTE_OUVERTURE') {
    if (etatVanne.toLowerCase().includes("ouvert")) {
        flow.set('arrosage_debut', now);
        flow.set('arrosage_state', 'ARROSAGE');
        const solData = flow.get('capteur_sol_data') || {};
        flow.set('arrosage_humidite_avant', solData.humidity || null);
        node.warn(`[ORCHESTRE] Vanne OUVERTE → chrono + humidité_avant=${solData.humidity}%`);
        return [msg, null];
    } else {
        // Relance UNIQUEMENT si cooldown écoulé
        if (!cooldownOk('relance OUVRIR')) return [msg, null];
        node.warn('[ORCHESTRE] Pas encore ouvert → relance OUVRIR');
        return [msg, sendCmd({ topic: "valve", origin: "auto", payload: { device_id: deviceId, command: cfg.openHex, origin: "auto" } })];
    }
}

if (state === 'ARROSAGE') {
    const ecoule  = now - (debut || now);
    const restant = dureeMs - ecoule;
    node.warn(`[ORCHESTRE] ARROSAGE — écoulé: ${Math.round(ecoule/1000)}s | restant: ${Math.round(restant/1000)}s`);

    if (restant <= 0) {
        if (!cooldownOk('envoi FERMER')) return [msg, null]; // Attendre le réveil suivant
        flow.set('arrosage_state', 'ATTENTE_FERMETURE');
        flow.set('arrosage_fin_ts', now);
        node.warn('[ORCHESTRE] Durée atteinte → envoi FERMER');
        return [msg, sendCmd({ topic: "valve", origin: "auto", payload: { device_id: deviceId, command: cfg.closeHex, origin: "auto" } })];
    }
    return [msg, null];
}

if (state === 'ATTENTE_FERMETURE') {
    if (etatVanne.toLowerCase().includes("ferm")) {
        const finTs          = flow.get('arrosage_fin_ts') || now;
        const debutTs        = flow.get('arrosage_debut')  || finTs;
        const dureeReelleMin = Math.round((finTs - debutTs) / 60000);
        const humAvant       = flow.get('arrosage_humidite_avant');

        flow.set('arrosage_state',  'IDLE');
        flow.set('arrosage_debut',  null);
        flow.set('attente_mesure_post', { ts: now, humAvant: humAvant, dureeMin: dureeReelleMin });
        node.warn(`[ORCHESTRE] Vanne FERMÉE — durée réelle: ${dureeReelleMin}min → attente avant config mode LENT`);

        // ⏳ DÉLAI : on attend le réveil SUIVANT pour envoyer la config 1E
        // Cela évite la saturation (02 → réponse → 1E trop rapide)
        // On stocke l'intention, l'Orchestre l'enverra au prochain réveil depuis IDLE
        flow.set('pending_config_lent', true);
        return [msg, null];
    } else {
        // Relance UNIQUEMENT si cooldown écoulé
        if (!cooldownOk('relance FERMER')) return [msg, null];
        node.warn('[ORCHESTRE] Pas encore fermé → relance FERMER');
        return [msg, sendCmd({ topic: "valve", origin: "auto", payload: { device_id: deviceId, command: cfg.closeHex, origin: "auto" } })];
    }
}

// IDLE — Envoi config mode lent différé (évite saturation après fermeture)
if (state === 'IDLE') {
    const pendingConfig = flow.get('pending_config_lent');
    if (pendingConfig) {
        if (!cooldownOk('config mode LENT')) return [msg, null];
        flow.set('pending_config_lent', false);
        node.warn('[ORCHESTRE] ✅ Envoi config 1E (mode lent) différé → réveil suivant OK');
        return [msg, sendCmd({ topic: "config", origin: "auto", payload: { device_id: deviceId, command: cfg.slowModeHex, origin: "auto" } })];
    }
}

// IDLE — Calibration post-arrosage
if (state === 'IDLE') {
    const attente = flow.get('attente_mesure_post');
    if (attente && attente.ts) {
        const observationDelayMin = Number(cfg.sensorObservationDelayMin || 120);
        const ecouleSinceFinMin = (now - attente.ts) / 60000;
        if (ecouleSinceFinMin >= observationDelayMin) {
            const solData    = flow.get('capteur_sol_data') || {};
            const humApres   = solData.humidity || null;
            const historique = flow.get('historique_arrosages') || [];

            const entree = {
                timestamp:      attente.ts,
                date:           new Date(attente.ts).toLocaleDateString('fr-FR', { timeZone: cfg.timezone || "Europe/Paris" }),
                duree_min:      attente.dureeMin,
                humidite_avant: attente.humAvant,
                humidite_apres: humApres,
                delta_hum:      (humApres !== null && attente.humAvant !== null) ? Math.round((humApres - attente.humAvant) * 10) / 10 : null,
                plant_profile:  (flow.get('plant_profile_state') || {}).profile?.label || (flow.get('active_plant_profile_key') || null),
                irrigation_type: cfg.irrigationType || 'souterrain',
                observation_delay_min: observationDelayMin
            };

            historique.unshift(entree);
            if (historique.length > 30) historique.pop();

            flow.set('historique_arrosages', historique);

            // Suivi capteur informatif uniquement.
            // La sécurité "capteur suspect / hausse insuffisante" a été retirée :
            // une humidité très basse doit pouvoir déclencher l'AUTO si les autres sécurités sont OK.
            let health = flow.get('capteur_health') || {};
            health.status = "OK";
            health.suspicious_active = false;
            health.reason = `Suivi informatif post-arrosage : ${attente.humAvant}% → ${humApres}% (delta ${entree.delta_hum}%)`;
            health.consecutive_no_response = 0;
            health.last_checked_ts = Date.now();
            health.last_delta_after_watering = entree.delta_hum;
            health.suspect_security_disabled = true;
            flow.set('capteur_health', health);

            flow.set('attente_mesure_post', null);
            node.warn(`[ORCHESTRE] 📊 Calibration (${observationDelayMin}min après fermeture): ${attente.dureeMin}min → ${attente.humAvant}% → ${humApres}% (delta: ${entree.delta_hum}%)`);
        }
    }
}

return [msg, null];

// --- CONFIGURATION ---
const MAX_LOGS = 50;
const STORAGE_KEY = "global_event_logs";
const TZJARDIN = (flow.get("config_jardin") || {}).timezone || "Europe/Paris";

let logs = flow.get(STORAGE_KEY) || [];
const now = new Date();
const timeStr = now.toLocaleTimeString('fr-FR', { timeZone: TZJARDIN, hour: '2-digit', minute: '2-digit', second: '2-digit' });

// Ouverture d'une page dashboard : on rejoue l'historique sans créer d'entrée
if (msg.topic === "$pageview") {
    msg.payload = logs;
    msg.topic = "event_log";
    return msg;
}

let newEntry = null;

// 0. FILTRE ANTI-SPAM MAINTENANCE
// Les messages maintenance_state servent souvent à rafraîchir l'affichage.
// On les ignore sauf si Set Maintenance marque explicitement msg.log_event = true.
if (msg.topic === "maintenance_state" && msg.log_event !== true) {
    return null;
}

// 1. ERREURS / MAINTENANCE
if (msg.payload && msg.payload.action === "ERREUR VANNE") {
    newEntry = { time: timeStr, msg: msg.payload.raison, type: "error", icon: "⚠️" };
}
else if (msg.topic === "maintenance_state" && msg.log_event === true) {
    newEntry = {
        time: timeStr,
        msg: msg.payload.maintenance_active ? "Mode maintenance activé" : "Mode maintenance désactivé",
        type: "user-config",
        icon: "🧰"
    };
}

// 2. ACTIONS UTILISATEUR
else if (msg.topic === "valve") {
    // Port 10 : commandes d'action vanne
    const cfgHex = Object.assign({ openHex: "01", closeHex: "02" }, flow.get("config_jardin") || {});
    let cmd = msg.payload.command;
    let txt = "Action inconnue";
    if (cmd === cfgHex.openHex)  txt = "Ordre : OUVRIR";
    if (cmd === cfgHex.closeHex) txt = "Ordre : FERMER";
    if (cmd === "80") txt = "Ping : Demande statut";

    newEntry = { time: timeStr, msg: txt, type: "user-action", icon: "👆" };
}
else if (msg.topic === "energy") {
    const p = msg.payload || {};
    newEntry = {
        time: timeStr,
        msg: p.message || "Évènement énergie EcoFlow",
        type: p.type || "error",
        icon: p.event === "ENERGY_RESUME" ? "🔋" : "🛑"
    };
}
else if (msg.topic === "config") {
    // Port 11 : configuration de la fréquence de réveil ("02" = 2 min ici, PAS "fermer")
    const cfgHex = Object.assign({ fastModeHex: "02", slowModeHex: "1E" }, flow.get("config_jardin") || {});
    let cmd = msg.payload.command;
    let txt = "Config inconnue";
    if (cmd === cfgHex.fastModeHex) txt = "Config : Mode RAPIDE (2m)";
    if (cmd === cfgHex.slowModeHex) txt = "Config : Mode ECO (30m)";

    newEntry = { time: timeStr, msg: txt, type: "user-config", icon: "⚙️" };
}

// 2b. DÉCISIONS IA (pré-check et analyse — relayées par 📊 Logger)
else if (msg.topic === "new-entry" && msg.payload && msg.payload.raison !== undefined) {
    const e = msg.payload;
    newEntry = {
        time: timeStr,
        msg: `IA : ${e.type || "décision"} — ${e.raison || ""}${e.duree ? " (" + e.duree + ")" : ""}`,
        type: e.typeClass === "arrosage" ? "success" : "info",
        icon: "🤖"
    };
}

// 3. DONNÉES CAPTEURS
else if (msg.payload && msg.payload.temperature !== undefined && msg.payload.humidity !== undefined) {
    newEntry = {
        time: timeStr,
        msg: `Sol : ${msg.payload.temperature}°C | ${msg.payload.humidity}%`,
        type: "sensor",
        icon: "🌱"
    };
}
else if (msg.payload && msg.payload.total_index !== undefined) {
    newEntry = {
        time: timeStr,
        msg: `Conso : ${msg.payload.consumed} L (Total: ${msg.payload.total_index})`,
        type: "water",
        icon: "💧"
    };
}
else if (msg.payload && msg.payload.state) {
    let etat = msg.payload.state;
    let icon = etat === "Ouvert" ? "✅" : "🔒";
    let type = etat === "Ouvert" ? "success" : "error";

    newEntry = {
        time: timeStr,
        msg: `Vanne confirmée : ${etat}`,
        type: type,
        icon: icon
    };
}

// 4. ENREGISTREMENT
if (!newEntry) return null;

logs.unshift(newEntry);
if (logs.length > MAX_LOGS) logs = logs.slice(0, MAX_LOGS);
flow.set(STORAGE_KEY, logs);

msg.payload = logs;
return msg;

// CAPTEUR SOL DRAGINO — lecture + suivi de fiabilité
// Objectif : ne pas considérer une humidité douteuse comme vérité absolue.

const cfg = Object.assign({ sensorDevice: "dragino-moisture" }, flow.get("config_jardin") || {});

function num(v) {
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : null;
}

// 1. Gestion structure TTN
let root = msg.payload;
if (root.data && root.data.uplink_message) {
    root = root.data;
}

// 2. Vérification device_id
const deviceId = root.end_device_ids?.device_id || msg.payload?.end_device_ids?.device_id || "inconnu";
if (deviceId !== cfg.sensorDevice) return null;

const now = Date.now();

// 3. Mémoire
let storedData = flow.get('capteur_sol_data') || {
    temperature: null,
    humidity: null,
    conductivity: null,
    battery: null,
    timestamp: null,
    previous_humidity: null,
    delta_from_previous: null
};

let health = flow.get('capteur_health') || {
    status: "OK",
    suspicious_active: false,
    reason: null,
    consecutive_no_response: 0,
    last_value: null,
    last_delta: null,
    last_update_ts: null,
    last_movement_ts: null,
    suspicious_since_ts: null,
    cleared_ts: null
};

const previousHumidity = num(storedData.humidity);

// 4. Extraction données Dragino
const uplink = root.uplink_message || {};
const decoded = uplink.decoded_payload || {};

if (decoded.temp_SOIL !== undefined) {
    storedData.temperature = num(decoded.temp_SOIL);
}

let newHumidity = previousHumidity;
if (decoded.water_SOIL !== undefined) {
    newHumidity = num(decoded.water_SOIL);
    if (newHumidity !== null) {
        storedData.previous_humidity = previousHumidity;
        storedData.humidity = newHumidity;
        storedData.delta_from_previous = previousHumidity !== null
            ? Math.round((newHumidity - previousHumidity) * 10) / 10
            : null;

        health.last_value = newHumidity;
        health.last_update_ts = now;
        health.last_delta = storedData.delta_from_previous;

        if (previousHumidity === null || Math.abs(newHumidity - previousHumidity) >= 1) {
            health.last_movement_ts = now;
        }

        // Sécurité capteur suspect désactivée : toute valeur basse reste utilisable pour piloter l'arrosage.
        health.suspicious_active = false;
        health.status = "OK";
        health.reason = `Lecture capteur acceptée : humidité ${newHumidity}%`;
        health.consecutive_no_response = 0;
        health.cleared_ts = now;
        health.suspect_security_disabled = true;
    }
}

if (decoded.conduct_SOIL !== undefined) {
    storedData.conductivity = decoded.conduct_SOIL;
}

// Batterie Dragino en volts → % estimé
if (decoded.BatV !== undefined) {
    let volts = parseFloat(decoded.BatV);
    let pct = ((volts - 2.5) / (3.6 - 2.5)) * 100;
    if (pct > 100) pct = 100;
    if (pct < 0) pct = 0;
    storedData.battery = Math.round(pct);
}

storedData.timestamp = now;
storedData.device_id = deviceId;
storedData.health = {
    status: health.status,
    suspicious_active: health.suspicious_active,
    reason: health.reason,
    consecutive_no_response: health.consecutive_no_response
};

flow.set('capteur_sol_data', storedData);
flow.set('capteur_health', health);

node.status({
    fill: "green",
    shape: "dot",
    text: `Sol: ${storedData.humidity ?? '--'}% | OK`
});

msg.payload = storedData;
return msg;

// Sauvegarde du switch AUTO.
// Si maintenance active ou coupure énergie EcoFlow, on interdit d'activer AUTO.
let requested = msg.payload === true;
// Arrêt volontaire de l'utilisateur : on annule tout réarmement automatique
if (msg.payload === false) flow.set('auto_before_cutoff', null);
const maintenance = flow.get('maintenance_active') === true;

const ecoLast = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");
const ecoAgeMin = ecoLast ? Math.round((Date.now() - Number(ecoLast)) / 60000) : null;
const ecoGuard = global.get("ecoflow_guard") === true; // sécurité EcoFlow réactivable depuis la page Réglages
const ecoStale = ecoGuard && (ecoAgeMin === null || ecoAgeMin > 15);
const ecoCutoff = ecoGuard && (global.get("energy_cutoff") === true || global.get("energie_ok") === false);

if (maintenance && requested) {
    requested = false;
    node.warn('[AUTO] Activation refusée : mode maintenance actif');
}

if ((ecoCutoff || ecoStale) && requested) {
    requested = false;
    node.warn(`[AUTO] Activation refusée : sécurité EcoFlow active | SOC=${global.get("ecoflow_soc") ?? "--"}% | âge=${ecoAgeMin ?? "--"}min`);
}

flow.set('auto_active', requested);
msg.topic = 'auto_state';
msg.payload = requested;
msg.auto_active = requested;
msg.maintenance_active = maintenance;
msg.energy_cutoff = ecoCutoff;
return msg;

msg.payload = flow.get('auto_active') || false;
msg.topic = "auto_state";
msg.maintenance_active = flow.get('maintenance_active') || false;
return msg;

// En mode AUTO (IA), l'Orchestre gère les changements de mode → pas de setTimeout
const isAuto = flow.get('auto_active') || false;

if (msg.topic === "valve") {
    const cmd = msg.payload.command;
    const deviceId = msg.payload.device_id;

    if (isAuto) {
        // Mode IA : transmettre la commande SANS setTimeout pour éviter les rafales
        return msg;
    }

    // Mode MANUEL : comportement original avec changement de fréquence auto
    const dernierEnvoi = flow.get("last_config_send_ts") || 0;
    const now = Date.now();
    const delaiMin = 6000;

    node.send([msg]);
    if ((now - dernierEnvoi) > delaiMin) {
        flow.set("last_config_send_ts", now + 4000);
        const cfg = Object.assign({ openHex: "01", fastModeHex: "02", slowModeHex: "1E" }, flow.get("config_jardin") || {});
        // OUVRIR (port 10) => passage en mode RAPIDE ; sinon retour mode ECO (port 11)
        const configCmd = (cmd === cfg.openHex) ? cfg.fastModeHex : cfg.slowModeHex;
        setTimeout(() => node.send([{
            topic: "config",
            payload: { device_id: deviceId, command: configCmd }
        }]), 5000);
    }
    return null;
}

return msg;

// PRÉ-CHECK NODE-RED v6 — IA = conseiller, Node-RED garde la sécurité
// Ajout : profils de plantes + arrosage souterrain + capteur calibré max 25%.
// Ajout v6 : quota débitmètre journalier 200 L pour bloquer uniquement l'AUTO.
// Ajout v7 : retrait du blocage capteur suspect. Une humidité très basse reste prioritaire.

const DEFAULT_CONFIG = {
    maxSolAgeMin: 180,
    maxMeteoAgeMin: 120,
    minHour: 7,
    maxHour: 20,
    rainDailyBlockMm: 3,
    rainPop3hBlockPct: 60,
    minHoursBetweenWatering: 6,
    minConfidence: 0.55,
    maxIrrigationMin: 5,
    maxValveStateAgeMin: 240,
    irrigationType: "souterrain",
    sensorObservationDelayMin: 180,
    sensorScaleMode: "calibre_bas_25pct",
    sensorWetMaxPct: 25,
    sensorComfortPct: 22,
    sensorDryPct: 15,

    maxAutoWateringsPerDay: 2,
    dailyWaterQuotaL: 200,
    sensorSuspiciousLowPct: 14,
    sensorMinRiseAfterWateringPct: 1,
    sensorSuspiciousAfterWaterings: 3,
    sensorHardMinPct: 0,
    sensorHardMaxPct: 100,
    activePlantProfile: "permaculture_mix",
    plantProfiles: {}
};
const CONFIG = Object.assign({}, DEFAULT_CONFIG, flow.get("config_jardin") || {});
const TZJARDIN = CONFIG.timezone || "Europe/Paris";

function num(v) {
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : null;
}
function ageMin(ts) {
    if (ts === undefined || ts === null || ts === "") return null;
    const n = Number(ts);
    if (!Number.isFinite(n)) return null;
    return Math.max(0, Math.round((Date.now() - n) / 60000));
}
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function fmtPct(v) { return Number.isFinite(v) ? `${v}%` : "--"; }
function fmtMm(v) { return Number.isFinite(v) ? `${v}mm` : "--"; }
function valveLooksOpen(state) {
    const s = String(state || "").toLowerCase();
    return s.includes("ouvert") || s.includes("open");
}
function dayKey(ts) {
    // Jour calendaire dans le fuseau du jardin (indépendant du fuseau du serveur)
    const d = ts ? new Date(ts) : new Date();
    return d.toLocaleDateString('en-CA', { timeZone: TZJARDIN });
}
function buildLogEntry(duree, raison, hum, pluie, deficit, methode, extra = {}) {
    const now = new Date();
    return Object.assign({
        ts:        now.getTime(),
        date:      now.toLocaleDateString('fr-FR', { timeZone: TZJARDIN, weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }),
        heure:     now.toLocaleTimeString('fr-FR', { timeZone: TZJARDIN, hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        type:      duree > 0 ? "ARROSAGE" : "VEILLE",
        typeClass: duree > 0 ? "type-arrosage" : "type-veille",
        duree,
        raison,
        humidite:  fmtPct(hum),
        pluie:     fmtMm(pluie),
        deficit:   fmtPct(deficit),
        methode
    }, extra);
}
function logEntry(entry) {
    let log = global.get("ia_command_log") || [];
    log.unshift(entry);
    if (log.length > 200) log = log.slice(0, 200);
    global.set("ia_command_log", log);
}
function veille(raison, methode, extra = {}) {
    node.warn(`[IA PRÉ-CHECK] VEILLE — ${raison}`);
    const entry = buildLogEntry(0, raison, extra.humSol, extra.pluie, extra.deficit, methode || "pre-check", {
        confiance: extra.confiance ?? null,
        age_capteur_min: extra.ageSolMin ?? null,
        age_meteo_min: extra.ageMeteoMin ?? null,
        etat_vanne: extra.etatVanne ?? null,
        capteur_status: extra.capteurStatus ?? null,
        arrosages_aujourdhui: extra.arrosagesAujourdhui ?? null,
        plant_profile: extra.plantProfileLabel ?? null,
        irrigation_type: extra.irrigationType ?? null,
        seuil_declenchement_pct: extra.cibleMin ?? null,
        objectif_pct: extra.targetPct ?? null
    });
    logEntry(entry);
    node.send([null, {
        payload: {
            action: extra.action || "VEILLE",
            raison,
            deficit: Number.isFinite(extra.deficit) ? extra.deficit : null,
            methode: methode || "pre-check",
            confiance: extra.confiance ?? null,
            age_capteur_min: extra.ageSolMin ?? null,
            age_meteo_min: extra.ageMeteoMin ?? null,
            capteur_status: extra.capteurStatus ?? null,
            arrosages_aujourdhui: extra.arrosagesAujourdhui ?? null,
            plant_profile_label: extra.plantProfileLabel ?? null,
            irrigation_type: extra.irrigationType ?? null,
            seuil_declenchement_pct: extra.cibleMin ?? null,
            objectif_pct: extra.targetPct ?? null
        }
    }, { topic: "new-entry", payload: entry }]);
    return null;
}

// 0. Mode maintenance
if (flow.get("maintenance_active") === true) {
    return veille("Mode maintenance actif — IA et automatisme bloqués. Commandes manuelles uniquement.", "maintenance", {
        action: "MAINTENANCE"
    });
}

// 1. Sécurité énergie EcoFlow
const ecoLast = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");
const ecoAgeMin = ageMin(ecoLast);
const ecoGuard = global.get("ecoflow_guard") === true; // sécurité EcoFlow réactivable depuis la page Réglages
const ecoStale = ecoGuard && (ecoAgeMin === null || ecoAgeMin > 15);
const ecoCutoff = ecoGuard && (global.get("energy_cutoff") === true || global.get("energie_ok") === false);
const ecoSoc = global.get("ecoflow_soc");

if (ecoCutoff || ecoStale) {
    if (flow.get("auto_active") === true) flow.set("auto_before_cutoff", true);
    flow.set("auto_active", false);
    flow.set("arrosage_state", "IDLE");
    flow.set("arrosage_debut", null);
    flow.set("arrosage_duree_ms", 0);
    flow.set("pending_config_lent", false);
    return veille(
        `Sécurité EcoFlow active — AUTO bloqué, SOC=${ecoSoc ?? "--"}%, données=${ecoAgeMin === null ? "absentes" : ecoAgeMin + "min"}. Attente recharge.`,
        "energy-cutoff",
        {
            action: "ENERGY CUTOFF",
            confiance: 1
        }
    );
}

// 2. Kill switch AUTO
if (flow.get('auto_active') !== true) {
    return veille("Mode MANUEL — basculez sur AUTO pour activer l'aide au pilotage IA.", "manuel", {
        action: "MODE MANUEL"
    });
}

// 2. État d'orchestration
const arrosageState = flow.get("arrosage_state") || "IDLE";
if (arrosageState !== "IDLE") {
    return veille(`Automatisme occupé : état ${arrosageState}. Nouvelle décision IA ignorée.`, "collision");
}

// 3. Récupération des données
const sol     = flow.get('capteur_sol_data') || {};
const vanne   = flow.get('valve_state') || flow.get('vanne_lyva_state') || {};
const weather = global.get('meteo_live')     || {};
let capteurHealth = flow.get('capteur_health') || {};

const humSol = num(sol.humidity);
const tempSol = num(sol.temperature);
const ageSolMin = ageMin(sol.timestamp);

const weatherTs = weather.timestamp || weather.updatedAtTs || weather._timestamp || weather.ts;
const ageMeteoMin = ageMin(weatherTs);

const heure = Number(new Intl.DateTimeFormat('en-GB', { timeZone: TZJARDIN, hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
const pluie = num(weather?.details?.rain) ?? 0;
const tempMeteo = num(weather?.header?.temp);
const temp = tempMeteo ?? tempSol ?? 20;

let probaPluie3h = 0;
if (Array.isArray(weather.hourly) && weather.hourly.length > 0) {
    for (let i = 0; i < 3; i++) {
        if (weather.hourly[i] && weather.hourly[i].pop !== undefined) {
            const p = num(weather.hourly[i].pop);
            if (p !== null) probaPluie3h = Math.max(probaPluie3h, p);
        }
    }
}

// Historique arrosages
const historique = flow.get('historique_arrosages') || [];
const today = dayKey(Date.now());
let arrosagesAujourdhui = historique.filter(h => h && h.timestamp && dayKey(h.timestamp) === today).length;

// v8 : un arrosage terminé mais pas encore calibré (fenêtre d'observation ~3h)
// n'est pas encore dans l'historique. On le prend en compte ici pour que
// minHoursBetweenWatering et la limite jour s'appliquent immédiatement.
const attentePost = flow.get('attente_mesure_post') || null;
const dernierFinTs = Number(flow.get('arrosage_fin_ts')) || 0;
const pendingArrosageTs = Math.max(attentePost && attentePost.ts ? Number(attentePost.ts) : 0, dernierFinTs) || null;
if (attentePost && attentePost.ts && dayKey(attentePost.ts) === today) {
    arrosagesAujourdhui += 1;
}

// Quota débitmètre journalier
const waterQuotaState = flow.get("water_quota_state") || {};
const dailyWaterQuotaL = num(CONFIG.dailyWaterQuotaL) ?? 200;
const waterQuotaDayKey = waterQuotaState.dayKey || null;
const waterQuotaIsToday = waterQuotaDayKey === today;
// Si le dernier état quota appartient à un ancien jour, on ne bloque pas l'AUTO.
// Le prochain uplink débitmètre recalera le compteur du jour.
const waterConsumedTodayL = waterQuotaIsToday ? num(waterQuotaState.consumed) : 0;
const waterRemainingTodayL = waterConsumedTodayL !== null ? Math.max(0, dailyWaterQuotaL - waterConsumedTodayL) : dailyWaterQuotaL;
const waterQuotaReached = waterQuotaIsToday && (waterQuotaState.reached === true || (waterConsumedTodayL !== null && waterConsumedTodayL >= dailyWaterQuotaL));

const dernierArrosage = historique[0] || null;
// v8 : le dernier arrosage réel peut être plus récent que l'historique (calibration différée).
// Math.floor (et non round) pour ne jamais sous-estimer la contrainte d'écart minimum.
const dernierArrosageTs = Math.max(
    dernierArrosage && dernierArrosage.timestamp ? Number(dernierArrosage.timestamp) : 0,
    pendingArrosageTs || 0
) || null;
const dernierArrosageH = dernierArrosageTs
    ? Math.floor((Date.now() - dernierArrosageTs) / 3600000)
    : null;

// Saison
const mois = Number(new Intl.DateTimeFormat('en-GB', { timeZone: TZJARDIN, month: 'numeric' }).format(new Date()));
const saison = (mois >= 6 && mois <= 8) ? 'ete' : ((mois >= 12 || mois <= 2) ? 'hiver' : 'mi-saison');

// Profil plante actif
const profiles = CONFIG.plantProfiles || {};
let activePlantProfileKey = flow.get("active_plant_profile_key") || CONFIG.activePlantProfile || "permaculture_mix";
if (!profiles[activePlantProfileKey] && profiles.permaculture_mix) activePlantProfileKey = "permaculture_mix";
const profile = Object.assign({
    label: activePlantProfileKey,
    triggerPct: saison === 'ete' ? 18 : 17,
    targetPct: saison === 'ete' ? 23 : 22,
    maxPct: 25,
    minHoursBetweenWatering: CONFIG.minHoursBetweenWatering,
    maxAutoWateringsPerDay: CONFIG.maxAutoWateringsPerDay,
    maxIrrigationMin: CONFIG.maxIrrigationMin,
    summerAdjustPct: 0,
    winterAdjustPct: 0
}, profiles[activePlantProfileKey] || {});

const seasonAdj = saison === 'ete' ? (num(profile.summerAdjustPct) ?? 0) : (saison === 'hiver' ? (num(profile.winterAdjustPct) ?? 0) : 0);
const sensorWetMaxPct = num(CONFIG.sensorWetMaxPct) ?? 25;
const cibleMin = clamp(Math.round((num(profile.triggerPct) ?? 17) + seasonAdj), 0, sensorWetMaxPct);
const targetPct = clamp(Math.round((num(profile.targetPct) ?? 22) + seasonAdj), 0, sensorWetMaxPct);
const cibleMax = clamp(Math.round((num(profile.maxPct) ?? sensorWetMaxPct) + seasonAdj), 0, sensorWetMaxPct);
const effectiveMinHours = num(profile.minHoursBetweenWatering) ?? CONFIG.minHoursBetweenWatering;
const effectiveMaxWateringsDay = num(profile.maxAutoWateringsPerDay) ?? CONFIG.maxAutoWateringsPerDay;
const effectiveMaxIrrigationMin = num(profile.maxIrrigationMin) ?? CONFIG.maxIrrigationMin;

const effectiveConfig = Object.assign({}, CONFIG, {
    minHoursBetweenWatering: effectiveMinHours,
    maxAutoWateringsPerDay: effectiveMaxWateringsDay,
    maxIrrigationMin: effectiveMaxIrrigationMin,
    activePlantProfileKey,
    activePlantProfileLabel: profile.label || activePlantProfileKey,
    activePlantProfile: profile,
    effectiveTriggerPct: cibleMin,
    effectiveTargetPct: targetPct,
    effectiveMaxPct: cibleMax,
    sensorScaleMode: CONFIG.sensorScaleMode || "calibre_bas_25pct",
    sensorWetMaxPct
});

const deficit = (humSol !== null) ? parseFloat((cibleMin - humSol).toFixed(1)) : null;

const etatVanne = vanne.confirmed_state || vanne.state || "inconnu";
const ageVanneMin = ageMin(vanne.last_confirmed_ts || vanne.state_confirmed_ts || vanne.timestamp || vanne.last_seen_ts);

// 3b. Sécurité capteur suspect désactivée.
// Le capteur est utilisé comme indicateur de pilotage, pas comme blocage AUTO.
// Si l'humidité est très basse, le système peut arroser tant que les autres sécurités sont OK.
capteurHealth.suspicious_active = false;
capteurHealth.status = "OK";
capteurHealth.reason = "Sécurité capteur suspect désactivée : la valeur basse déclenche selon seuil plante.";
capteurHealth.suspect_security_disabled = true;
flow.set('capteur_health', capteurHealth);
const capteurStatus = "OK";

const common = {
    humSol,
    pluie,
    deficit,
    ageSolMin,
    ageMeteoMin,
    etatVanne,
    capteurStatus,
    arrosagesAujourdhui,
    plantProfileLabel: profile.label || activePlantProfileKey,
    irrigationType: CONFIG.irrigationType,
    cibleMin,
    targetPct,
    waterConsumedTodayL,
    dailyWaterQuotaL,
    waterRemainingTodayL,
    waterQuotaReached
};

const REGLES = [
    { test: humSol === null || humSol < CONFIG.sensorHardMinPct || humSol > CONFIG.sensorHardMaxPct, raison: `Donnée capteur sol invalide ou absente : ${sol.humidity ?? "absente"}` },
    { test: arrosagesAujourdhui >= effectiveMaxWateringsDay, raison: `Limite d'arrosages automatiques atteinte aujourd'hui : ${arrosagesAujourdhui}/${effectiveMaxWateringsDay}` },
    { test: waterQuotaReached === true, raison: `Quota eau journalier atteint : ${waterConsumedTodayL ?? dailyWaterQuotaL}/${dailyWaterQuotaL} L. AUTO bloqué jusqu’au reset journalier ou reset manuel.` },
    { test: ageSolMin === null, raison: "Aucun timestamp capteur sol disponible — donnée LoRaWAN non confirmée" },
    { test: ageSolMin !== null && ageSolMin > CONFIG.maxSolAgeMin, raison: `Donnée capteur sol trop ancienne : ${ageSolMin}min > ${CONFIG.maxSolAgeMin}min` },
    { test: !weather.details || !Array.isArray(weather.hourly), raison: "Données météo absentes ou incomplètes" },
    { test: ageMeteoMin === null, raison: "Aucun timestamp météo disponible — attendre le prochain rafraîchissement météo" },
    { test: ageMeteoMin !== null && ageMeteoMin > CONFIG.maxMeteoAgeMin, raison: `Donnée météo trop ancienne : ${ageMeteoMin}min > ${CONFIG.maxMeteoAgeMin}min` },
    { test: valveLooksOpen(etatVanne), raison: `Vanne déjà signalée ouverte (${etatVanne}) — pas de nouvelle commande` },
    { test: ageVanneMin !== null && ageVanneMin > CONFIG.maxValveStateAgeMin, raison: `État vanne trop ancien : ${ageVanneMin}min > ${CONFIG.maxValveStateAgeMin}min` },
    { test: humSol !== null && humSol >= cibleMin, raison: `Sol à ${humSol}% ≥ seuil ${cibleMin}% (${profile.label || activePlantProfileKey}) — pas besoin d'arroser` },
    { test: heure < CONFIG.minHour || heure > CONFIG.maxHour, raison: `Hors plage horaire (${heure}h) — arrosage autorisé ${CONFIG.minHour}h-${CONFIG.maxHour}h` },
    { test: pluie > CONFIG.rainDailyBlockMm, raison: `Pluie journalière ${pluie}mm > ${CONFIG.rainDailyBlockMm}mm — arrosage bloqué` },
    { test: probaPluie3h > CONFIG.rainPop3hBlockPct, raison: `Probabilité pluie dans 3h : ${probaPluie3h}% > ${CONFIG.rainPop3hBlockPct}%` },
    { test: dernierArrosageH !== null && dernierArrosageH < effectiveMinHours, raison: `Dernier arrosage il y a ${dernierArrosageH}h < ${effectiveMinHours}h — trop tôt pour le profil ${profile.label || activePlantProfileKey}` },
    { test: deficit !== null && deficit <= 0, raison: `Déficit nul ou négatif (${deficit}%) — arrosage inutile` }
];

for (const regle of REGLES) {
    if (regle.test) return veille(regle.raison, "pre-check", common);
}

// Calibration simple à partir de l'historique
let efficaciteParMin = null;
if (historique.length >= 2) {
    let totalDelta = 0, totalDuree = 0, count = 0;
    historique.slice(0, 5).forEach(h => {
        if (h.humidite_avant !== null && h.humidite_apres !== null && h.duree_min > 0) {
            totalDelta += (h.humidite_apres - h.humidite_avant);
            totalDuree += h.duree_min;
            count++;
        }
    });
    if (count > 0 && totalDuree > 0) {
        efficaciteParMin = Math.round((totalDelta / totalDuree) * 10) / 10;
    }
}

const ctx = {
    source: "LoRaWAN + Open-Meteo",
    donnees_ok: true,
    config: effectiveConfig,
    humSol,
    temp,
    cibleMin,
    cibleMax,
    targetPct,
    deficit,
    saison,
    heure,
    pluie,
    probaPluie3h,
    dernierArrosageH,
    dernierHumApres: dernierArrosage ? dernierArrosage.humidite_apres : null,
    efficaciteParMin,
    nbArrosages: historique.length,
    arrosagesAujourdhui,
    maxArrosagesJour: effectiveMaxWateringsDay,
    minHoursBetweenWatering: effectiveMinHours,
    etatVanne,
    age_donnee_capteur_min: ageSolMin,
    age_meteo_min: ageMeteoMin,
    age_etat_vanne_min: ageVanneMin,
    batterie_capteur: sol.battery ?? null,
    batterie_vanne: vanne.battery ?? null,
    capteur_fiable: true,
    capteur_status: "OK",
    capteur_raison: "Sécurité capteur suspect désactivée",
    seuil_capteur_suspect_pct: null,
    min_hausse_attendue_pct: null,
    irrigation_type: CONFIG.irrigationType,
    sensor_observation_delay_min: CONFIG.sensorObservationDelayMin,
    active_plant_profile_key: activePlantProfileKey,
    active_plant_profile_label: profile.label || activePlantProfileKey,
    active_plant_profile_description: profile.description || null,
    sensor_scale_mode: CONFIG.sensorScaleMode || "calibre_bas_25pct",
    sensor_wet_max_pct: sensorWetMaxPct,
    sensor_comfort_pct: CONFIG.sensorComfortPct ?? 22,
    sensor_dry_pct: CONFIG.sensorDryPct ?? 15,
    water_quota_l: dailyWaterQuotaL,
    water_consumed_today_l: waterConsumedTodayL,
    water_remaining_today_l: waterRemainingTodayL,
    water_quota_reached: waterQuotaReached,
    water_quota_day_key: waterQuotaDayKey,
    plant_profile: profile
};

flow.set('ia_ctx', ctx);
msg.ia_ctx = ctx;

node.warn(`[IA PRÉ-CHECK] OK — Profil ${profile.label || activePlantProfileKey} | ${CONFIG.irrigationType} | Sol ${humSol}% | seuil ${cibleMin}% | déficit ${deficit}% | ${arrosagesAujourdhui}/${effectiveMaxWateringsDay} | Eau ${waterConsumedTodayL ?? 0}/${dailyWaterQuotaL}L → conseil IA`);
return [msg, null, null];

// PARSE & DECIDE v6
// OpenAI conseille. Node-RED valide, bloque ou lance l'arrosage.
// Ajout : profil plante + arrosage souterrain + capteur calibré max 25%.
// Ajout v6 : quota débitmètre journalier. Si atteint, AUTO bloqué mais MANUEL conservé.
// Ajout v7 : suppression du blocker capteur suspect.

const ctx = flow.get('ia_ctx') || {};
const cfg = ctx.config || {};
const TZJARDIN = cfg.timezone || "Europe/Paris";
const maxMin = cfg.maxIrrigationMin || 5;
const minConfidence = cfg.minConfidence || 0.55;

function n(v) {
    const x = parseFloat(v);
    return Number.isFinite(x) ? x : null;
}
function valveLooksOpen(state) {
    const s = String(state || "").toLowerCase();
    return s.includes("ouvert") || s.includes("open");
}
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function parseOpenAIResponse(msg) {
    if (!msg.payload || !msg.payload.choices || !msg.payload.choices[0]?.message?.content) {
        throw new Error("Réponse OpenAI invalide ou vide");
    }
    let raw = msg.payload.choices[0].message.content.trim();
    raw = raw.replace(/^`{1,3}(?:json)?\s*/i, '').replace(/\s*`{1,3}$/i, '').trim();
    return JSON.parse(raw);
}
function buildEntry(duree, raison, methode, extra = {}) {
    const now = new Date();
    return Object.assign({
        ts:        now.getTime(),
        date:      now.toLocaleDateString('fr-FR', { timeZone: TZJARDIN, weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }),
        heure:     now.toLocaleTimeString('fr-FR', { timeZone: TZJARDIN, hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        type:      duree > 0 ? "ARROSAGE" : "VEILLE",
        typeClass: duree > 0 ? "type-arrosage" : "type-veille",
        duree,
        raison,
        humidite:  (ctx.humSol ?? "--") + "%",
        pluie:     (ctx.pluie ?? "--") + "mm",
        deficit:   (ctx.deficit ?? "--") + "%",
        methode,
        plant_profile: ctx.active_plant_profile_label || null,
        irrigation_type: ctx.irrigation_type || null,
        seuil_declenchement_pct: ctx.cibleMin ?? null,
        objectif_pct: ctx.targetPct ?? null,
        water_consumed_today_l: ctx.water_consumed_today_l ?? null,
        water_quota_l: ctx.water_quota_l ?? null,
        water_remaining_today_l: ctx.water_remaining_today_l ?? null,
        water_quota_reached: ctx.water_quota_reached ?? null
    }, extra);
}
function pushLog(entry) {
    let log = global.get("ia_command_log") || [];
    log.unshift(entry);
    if (log.length > 200) log = log.slice(0, 200);
    global.set("ia_command_log", log);
}
function ui(action, raison, duree, methode, confiance) {
    return {
        payload: {
            action,
            raison,
            duree,
            deficit: ctx.deficit ?? null,
            methode,
            confiance,
            age_capteur_min: ctx.age_donnee_capteur_min ?? null,
            age_meteo_min: ctx.age_meteo_min ?? null,
            capteur_status: ctx.capteur_status ?? null,
            arrosages_aujourdhui: ctx.arrosagesAujourdhui ?? null,
            plant_profile_label: ctx.active_plant_profile_label ?? null,
            irrigation_type: ctx.irrigation_type ?? null,
            seuil_declenchement_pct: ctx.cibleMin ?? null,
            objectif_pct: ctx.targetPct ?? null,
            water_consumed_today_l: ctx.water_consumed_today_l ?? null,
            water_quota_l: ctx.water_quota_l ?? null,
            water_remaining_today_l: ctx.water_remaining_today_l ?? null,
            water_quota_reached: ctx.water_quota_reached ?? null
        }
    };
}

let decision = {};
try {
    decision = parseOpenAIResponse(msg);
} catch(e) {
    const raison = "[IA] Réponse JSON inexploitable : " + e.message;
    node.error(raison);
    const entry = buildEntry(0, raison, "openai-error", { type: "VEILLE", typeClass: "type-veille", confiance: 0, age_capteur_min: ctx.age_donnee_capteur_min ?? null, age_meteo_min: ctx.age_meteo_min ?? null });
    pushLog(entry);
    return [null, ui("VEILLE", raison, 0, "openai-error", 0), { topic: "new-entry", payload: entry }];
}

let action = String(decision.action || "").toUpperCase().trim();
if (action !== "ARROSER" && action !== "VEILLE") action = n(decision.minutes) > 0 ? "ARROSER" : "VEILLE";

let confiance = n(decision.confiance);
if (confiance === null) confiance = 0;
confiance = clamp(confiance, 0, 1);

let duree = Math.round(n(decision.minutes) || 0);
let raison = String(decision.raison || "Décision IA sans explication").slice(0, 260);

if (action !== "ARROSER") duree = 0;
if (action === "ARROSER") {
    if (duree <= 0) {
        action = "VEILLE";
        duree = 0;
        raison = "IA a demandé ARROSER mais sans durée exploitable — veille par sécurité";
    } else {
        duree = clamp(duree, 1, maxMin);
    }
}

const blockers = [];
const humSol = n(ctx.humSol);
const cibleMin = n(ctx.cibleMin);
const heure = Number(new Intl.DateTimeFormat('en-GB', { timeZone: TZJARDIN, hour: 'numeric', hourCycle: 'h23' }).format(new Date()));

if (ctx.donnees_ok !== true) blockers.push("contexte IA marqué non fiable");
if (ctx.arrosagesAujourdhui !== null && ctx.arrosagesAujourdhui !== undefined && ctx.arrosagesAujourdhui >= (cfg.maxAutoWateringsPerDay || 2)) blockers.push(`limite arrosages jour atteinte (${ctx.arrosagesAujourdhui}/${cfg.maxAutoWateringsPerDay || 2})`);
if (ctx.water_quota_reached === true || (n(ctx.water_consumed_today_l) !== null && n(ctx.water_quota_l) !== null && n(ctx.water_consumed_today_l) >= n(ctx.water_quota_l))) blockers.push(`quota eau journalier atteint (${ctx.water_consumed_today_l ?? ctx.water_quota_l}/${ctx.water_quota_l || 200} L) — AUTO bloqué jusqu’au reset`);
if (ctx.age_donnee_capteur_min === null || ctx.age_donnee_capteur_min === undefined) blockers.push("âge capteur sol absent");
if (ctx.age_meteo_min === null || ctx.age_meteo_min === undefined) blockers.push("âge météo absent");
if (ctx.age_donnee_capteur_min > (cfg.maxSolAgeMin || 180)) blockers.push(`capteur sol trop ancien (${ctx.age_donnee_capteur_min}min)`);
if (ctx.age_meteo_min > (cfg.maxMeteoAgeMin || 120)) blockers.push(`météo trop ancienne (${ctx.age_meteo_min}min)`);
if (humSol !== null && cibleMin !== null && humSol >= cibleMin) blockers.push(`humidité suffisante (${humSol}% ≥ seuil ${cibleMin}% pour ${ctx.active_plant_profile_label || 'profil plante'})`);
if (heure < (cfg.minHour || 7) || heure > (cfg.maxHour || 20)) blockers.push(`hors plage horaire (${heure}h)`);
if ((ctx.pluie || 0) > (cfg.rainDailyBlockMm || 3)) blockers.push(`pluie journalière trop forte (${ctx.pluie}mm)`);
if ((ctx.probaPluie3h || 0) > (cfg.rainPop3hBlockPct || 60)) blockers.push(`pluie probable à 3h (${ctx.probaPluie3h}%)`);
if (ctx.dernierArrosageH !== null && ctx.dernierArrosageH < (cfg.minHoursBetweenWatering || 6)) blockers.push(`dernier arrosage trop récent (${ctx.dernierArrosageH}h < ${cfg.minHoursBetweenWatering || 6}h)`);
if (valveLooksOpen(ctx.etatVanne)) blockers.push(`vanne déjà ouverte (${ctx.etatVanne})`);
if (action === "ARROSER" && confiance < minConfidence) blockers.push(`confiance IA trop faible (${confiance})`);

const ecoLastDecision = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");
const ecoAgeDecisionMin = ecoLastDecision ? Math.round((Date.now() - Number(ecoLastDecision)) / 60000) : null;
const ecoGuard = global.get("ecoflow_guard") === true; // sécurité EcoFlow réactivable depuis la page Réglages
const ecoStaleDecision = ecoGuard && (ecoAgeDecisionMin === null || ecoAgeDecisionMin > 15);
const ecoCutoffDecision = ecoGuard && (global.get("energy_cutoff") === true || global.get("energie_ok") === false);
if (ecoCutoffDecision || ecoStaleDecision) blockers.push(`sécurité EcoFlow active (SOC=${global.get("ecoflow_soc") ?? "--"}%, âge=${ecoAgeDecisionMin ?? "--"}min)`);

if (flow.get("maintenance_active") === true) blockers.push("maintenance active");
const currentState = flow.get("arrosage_state") || "IDLE";
if (action === "ARROSER" && currentState !== "IDLE") blockers.push(`automatisme occupé (${currentState})`);

if (blockers.length > 0) {
    duree = 0;
    action = "VEILLE";
    raison = "Blocage Node-RED : " + blockers.join(" | ");
}

const entry = buildEntry(duree, raison, "openai+validation", {
    type: duree > 0 ? "ARROSAGE" : (blockers.length > 0 ? "BLOQUÉ" : "VEILLE"),
    typeClass: duree > 0 ? "type-arrosage" : "type-veille",
    confiance,
    action_ia: decision.action || null,
    age_capteur_min: ctx.age_donnee_capteur_min ?? null,
    age_meteo_min: ctx.age_meteo_min ?? null,
    etat_vanne: ctx.etatVanne ?? null,
    capteur_status: ctx.capteur_status ?? null,
    arrosages_aujourdhui: ctx.arrosagesAujourdhui ?? null,
    water_consumed_today_l: ctx.water_consumed_today_l ?? null,
    water_quota_l: ctx.water_quota_l ?? null,
    water_quota_reached: ctx.water_quota_reached ?? null
});
pushLog(entry);

node.warn(`[IA PARSE] ${duree > 0 ? "ARROSAGE " + duree + "min" : "VEILLE"} | ${ctx.active_plant_profile_label || 'profil'} | confiance ${confiance} | ${raison}`);

const msgUI = ui(duree > 0 ? "ARROSAGE " + duree + " min" : "VEILLE", raison, duree, entry.methode, confiance);
const msgLog = { topic: "new-entry", payload: entry };

if (duree <= 0) return [null, msgUI, msgLog];

flow.set("arrosage_state",    "PREP_RAPIDE");
flow.set("arrosage_duree_ms", duree * 60 * 1000);
flow.set("arrosage_debut",    null);
flow.set("arrosage_device",   (cfg.valveDevice || "lyva-tre"));

node.warn(`[IA PARSE] 🚿 Demande validée — ${ctx.active_plant_profile_label || 'profil plante'} — préparation mode rapide puis arrosage ${duree}min`);

return [
    { topic: "config", origin: "auto", payload: { device_id: (cfg.valveDevice || "lyva-tre"), command: (cfg.fastModeHex || "02"), origin: "auto" } },
    msgUI,
    msgLog
];

const log = global.get('ia_command_log') || [];
msg.topic = 'init-log';
msg.payload = log;
return msg;

const old = flow.get('arrosage_state') || 'IDLE';
flow.set('arrosage_state', 'IDLE');
flow.set('arrosage_debut', null);
flow.set('arrosage_duree_ms', 0);
flow.set('pending_config_lent', false);
flow.set('arrosage_fin_ts', null);

let vs = flow.get('valve_state');
if (vs) {
    vs.pending_command = null;
    vs.pending_state = null;
    vs.pending_since_ts = null;
    vs.error = null;
    if (vs.confirmed_state) {
        const s = String(vs.confirmed_state).toLowerCase();
        vs.status = s.includes('ouvert') ? 'OPEN_CONFIRMED' : (s.includes('ferm') ? 'CLOSED_CONFIRMED' : 'UNKNOWN_CONFIRMED');
    }
    flow.set('valve_state', vs);
}

// Reset capteur : la sécurité suspect est désactivée en v7.
let ch = flow.get('capteur_health') || {};
ch.suspicious_active = false;
ch.status = "OK";
ch.reason = "Reset manuel — profil plante conservé";
ch.consecutive_no_response = 0;
ch.cleared_ts = Date.now();
flow.set('capteur_health', ch);

// Reset quota eau : libère immédiatement le blocage AUTO.
// Le débitmètre recalera son point zéro journalier au prochain uplink.
const quotaResetTs = Date.now();
flow.set("water_quota_reset_request_ts", quotaResetTs);
flow.set("water_quota_state", {
    dayKey: null,
    consumed: 0,
    quota: (flow.get("config_jardin") || {}).dailyWaterQuotaL || 200,
    remaining: (flow.get("config_jardin") || {}).dailyWaterQuotaL || 200,
    reached: false,
    percent: 0,
    timestamp: quotaResetTs,
    reset_pending_next_flowmeter_uplink: true
});

node.status({ fill: 'green', shape: 'dot', text: 'Reset OK — était: ' + old });
node.warn('[RESET] arrosage_state → IDLE (était: ' + old + ')');
return null;

// Restaure l'affichage du mode au démarrage / redéploiement
const mode = flow.get('vanne_current_mode');
if (mode === 2 || mode === 30) {
    msg.payload = { mode: mode };
    return msg;
}
// Mode encore inconnu (aucun uplink f_port 11 reçu) -> on n'affiche rien
return null;

// CONFIG JARDIN CENTRALISÉE v7
// Ajout v5 : capteur calibré sur plage basse. Chez ce système,
// 20-25% correspond déjà à une zone humide correcte en arrosage souterrain.
// Modifier ces valeurs ici plutôt que dans chaque nœud.

const DEFAULT_CONFIG = {
    configSchemaVersion: 7,

    // Fuseau horaire de référence (plages horaires, saisons, resets journaliers).
    timezone: "Europe/Paris",

    appId: "jardin-version1",
    valveDevice: "lyva-tre",
    sensorDevice: "dragino-moisture",
    flowmeterDevice: "debitmetre",

    surfaceM2: 24,
    theoreticalFlowLMin: 6,
    dailyWaterQuotaL: 200,

    // Arrosage souterrain : l'eau met du temps à atteindre la zone mesurée par le capteur.
    irrigationType: "souterrain",
    sensorObservationDelayMin: 180,

    // Plage réelle observée du capteur.
    // Ne pas viser 40-60% : sur ce montage, 20-25% = humide.
    sensorScaleMode: "calibre_bas_25pct",
    sensorWetMaxPct: 25,
    sensorComfortPct: 22,
    sensorDryPct: 15,

    minHour: 7,
    maxHour: 20,
    rainDailyBlockMm: 3,
    rainPop3hBlockPct: 60,
    minHoursBetweenWatering: 6,

    // Capteur calibré bas.
    // La sécurité "capteur suspect / hausse insuffisante" est désactivée :
    // une humidité très basse peut déclencher l'AUTO.
    maxAutoWateringsPerDay: 2,
    sensorSuspiciousLowPct: 14,
    sensorMinRiseAfterWateringPct: 1,
    sensorSuspiciousAfterWaterings: 3,
    sensorHardMinPct: 0,
    sensorHardMaxPct: 100,

    maxSolAgeMin: 180,
    maxMeteoAgeMin: 120,
    maxValveStateAgeMin: 240,

    minConfidence: 0.55,
    maxIrrigationMin: 5,

    commandTimeoutMin: 10,
    commandCooldownMs: 10000,

    // Port 10 (downlink action vanne)
    openHex: "01",      // OUVRIR (port 10)
    closeHex: "02",     // FERMER (port 10) — attention : même hex que fastModeHex mais port différent
    // Port 11 (downlink config fréquence de réveil)
    fastModeHex: "02",  // Mode RAPIDE 2 min (port 11)
    slowModeHex: "1E",  // Mode ECO 30 min (port 11)

    maintenanceDefault: false,

    activePlantProfile: "permaculture_mix",
    plantProfiles: {
        permaculture_mix: {
            label: "Permaculture mixte",
            description: "Profil prudent calibré capteur bas : 20-25% = sol humide en arrosage souterrain.",
            triggerPct: 17,
            targetPct: 22,
            maxPct: 25,
            minHoursBetweenWatering: 6,
            maxAutoWateringsPerDay: 2,
            maxIrrigationMin: 5,
            summerAdjustPct: 1,
            winterAdjustPct: -1
        },
        tomates_poivrons_aubergines: {
            label: "Tomates / poivrons / aubergines",
            description: "Légumes-fruits : arrosage profond, pas trop fréquent. Plage calibrée max 25%.",
            triggerPct: 17,
            targetPct: 22,
            maxPct: 25,
            minHoursBetweenWatering: 8,
            maxAutoWateringsPerDay: 2,
            maxIrrigationMin: 5,
            summerAdjustPct: 1,
            winterAdjustPct: -1
        },
        salades_feuilles: {
            label: "Salades / feuilles / basilic",
            description: "Plantes plus sensibles au stress hydrique, mais seuils adaptés au capteur bas.",
            triggerPct: 18,
            targetPct: 23,
            maxPct: 25,
            minHoursBetweenWatering: 6,
            maxAutoWateringsPerDay: 2,
            maxIrrigationMin: 5,
            summerAdjustPct: 1,
            winterAdjustPct: 0
        },
        courgettes_concombres: {
            label: "Courgettes / concombres",
            description: "Besoin en eau plus élevé, sans dépasser la plage utile réelle 20-25%.",
            triggerPct: 18,
            targetPct: 24,
            maxPct: 25,
            minHoursBetweenWatering: 6,
            maxAutoWateringsPerDay: 2,
            maxIrrigationMin: 5,
            summerAdjustPct: 1,
            winterAdjustPct: 0
        },
        aromatiques_mediterraneennes: {
            label: "Aromatiques méditerranéennes",
            description: "Thym, romarin, lavande : besoin faible, éviter l'excès d'eau.",
            triggerPct: 14,
            targetPct: 18,
            maxPct: 22,
            minHoursBetweenWatering: 12,
            maxAutoWateringsPerDay: 1,
            maxIrrigationMin: 3,
            summerAdjustPct: 1,
            winterAdjustPct: -1
        },
        semis_jeunes_plants: {
            label: "Semis / jeunes plants",
            description: "Besoin régulier, à utiliser seulement si le capteur est proche de la zone racinaire.",
            triggerPct: 19,
            targetPct: 24,
            maxPct: 25,
            minHoursBetweenWatering: 6,
            maxAutoWateringsPerDay: 2,
            maxIrrigationMin: 4,
            summerAdjustPct: 1,
            winterAdjustPct: 0
        }
    }
};

let current = flow.get("config_jardin") || {};
const previousVersion = Number(current.configSchemaVersion || 0);

let cfg = Object.assign({}, DEFAULT_CONFIG, current);
cfg.plantProfiles = Object.assign({}, DEFAULT_CONFIG.plantProfiles, current.plantProfiles || {});

// Sécurité : un fuseau horaire invalide ferait planter tous les calculs Intl en aval.
try {
    new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone });
} catch (e) {
    node.warn(`[CONFIG] Fuseau horaire invalide (${cfg.timezone}) — retour à Europe/Paris`);
    cfg.timezone = "Europe/Paris";
}

// Migration v5 : force les seuils calibrés bas si l'ancien contexte existait déjà.
// Cela évite de garder les anciens objectifs 30-40% impossibles à atteindre avec ce capteur.
if (previousVersion < 5) {
    cfg = Object.assign({}, cfg, {
        configSchemaVersion: 7,
        irrigationType: DEFAULT_CONFIG.irrigationType,
        sensorObservationDelayMin: DEFAULT_CONFIG.sensorObservationDelayMin,
        sensorScaleMode: DEFAULT_CONFIG.sensorScaleMode,
        sensorWetMaxPct: DEFAULT_CONFIG.sensorWetMaxPct,
        sensorComfortPct: DEFAULT_CONFIG.sensorComfortPct,
        sensorDryPct: DEFAULT_CONFIG.sensorDryPct,
        minHoursBetweenWatering: DEFAULT_CONFIG.minHoursBetweenWatering,
        maxAutoWateringsPerDay: DEFAULT_CONFIG.maxAutoWateringsPerDay,
        sensorSuspiciousLowPct: DEFAULT_CONFIG.sensorSuspiciousLowPct,
        sensorMinRiseAfterWateringPct: DEFAULT_CONFIG.sensorMinRiseAfterWateringPct,
        sensorSuspiciousAfterWaterings: DEFAULT_CONFIG.sensorSuspiciousAfterWaterings,
        activePlantProfile: current.activePlantProfile || DEFAULT_CONFIG.activePlantProfile
    });
    cfg.plantProfiles = DEFAULT_CONFIG.plantProfiles;
    flow.set('capteur_health', { status: "OK", suspicious_active: false, reason: "Migration v5 : plage capteur recalibrée 20-25%" });
}

// v7 : on neutralise définitivement l'ancien blocage capteur suspect.
flow.set('capteur_health', {
    status: "OK",
    suspicious_active: false,
    reason: "v7 : sécurité capteur suspect désactivée",
    consecutive_no_response: 0,
    suspect_security_disabled: true,
    cleared_ts: Date.now()
});

flow.set("config_jardin", cfg);

let activeKey = flow.get("active_plant_profile_key") || cfg.activePlantProfile || "permaculture_mix";
if (!cfg.plantProfiles[activeKey]) activeKey = "permaculture_mix";
flow.set("active_plant_profile_key", activeKey);
flow.set("plant_profile_state", {
    key: activeKey,
    profile: cfg.plantProfiles[activeKey],
    irrigation_type: cfg.irrigationType,
    sensor_observation_delay_min: cfg.sensorObservationDelayMin,
    sensor_scale_mode: cfg.sensorScaleMode,
    sensor_wet_max_pct: cfg.sensorWetMaxPct
});

if (flow.get("maintenance_active") === undefined) {
    flow.set("maintenance_active", cfg.maintenanceDefault === true);
}
if (!flow.get("arrosage_state")) {
    flow.set("arrosage_state", "IDLE");
}

node.status({ fill: "green", shape: "dot", text: `v7 OK | capteur critique autorisé | quota ${cfg.dailyWaterQuotaL}L | ${cfg.plantProfiles[activeKey]?.label || activeKey}` });
msg.topic = "config_jardin";
msg.payload = cfg;
return msg;

// MODE MAINTENANCE
// ON : bloque l'IA et l'automatisme. Les commandes manuelles restent possibles.
// Correctif V2 : pas de boucle ui-template + historique uniquement si changement réel.

const previousState = flow.get("maintenance_active") === true;
let state = previousState;
let changed = false;
let source = "refresh";

if (msg.topic === "set_maintenance") {
    source = "user";
    state = msg.payload === true;
    changed = (state !== previousState);

    flow.set("maintenance_active", state);

    if (state) {
        flow.set("auto_active", false);
        flow.set("arrosage_state", "IDLE");
        flow.set("arrosage_debut", null);
        flow.set("arrosage_duree_ms", 0);
        flow.set("pending_config_lent", false);
        node.warn("[MAINTENANCE] Activée — AUTO coupé et automatisme remis IDLE");
    } else {
        node.warn("[MAINTENANCE] Désactivée");
    }
}

msg.topic = "maintenance_state";
msg.payload = {
    maintenance_active: state,
    auto_active: flow.get("auto_active") === true,
    arrosage_state: flow.get("arrosage_state") || "IDLE",
    action: state ? "MAINTENANCE" : "VEILLE",
    raison: state ? "Mode maintenance actif — IA et automatisme bloqués." : "Mode maintenance désactivé.",
    source: source,
    changed: changed
};

msg.auto_active = flow.get("auto_active") === true;
msg.maintenance_active = state;

// Très important : le Logger Central ne doit journaliser que les vrais changements utilisateur.
msg.log_event = changed && source === "user";

return msg;

// WATCHDOG COMMANDE VANNE LoRaWAN
// Si une commande reste en attente trop longtemps, on bloque l'automatisme.
// Pas de sécurité débitmètre ici.

const cfg = Object.assign({ commandTimeoutMin: 10, valveDevice: "lyva-tre" }, flow.get("config_jardin") || {});
const vs = flow.get('valve_state');
if (!vs || !vs.pending_command || !vs.pending_since_ts) return null;

const now = Date.now();
const ageMin = (now - vs.pending_since_ts) / 60000;
if (ageMin <= cfg.commandTimeoutMin) return null;

const label = vs.pending_state || vs.pending_command;
const reason = `Timeout LoRaWAN : commande ${vs.pending_command} (${label}) non confirmée après ${Math.round(ageMin)}min`;

vs.status = label === "Ouvert" ? "ERROR_OPEN_TIMEOUT" : (label === "Fermé" ? "ERROR_CLOSE_TIMEOUT" : "ERROR_COMMAND_TIMEOUT");
vs.error = reason;
vs.pending_command = null;
vs.pending_state = null;
vs.pending_since_ts = null;
flow.set('valve_state', vs);
flow.set(`commande_en_attente_${vs.device_id || cfg.valveDevice}`, null);

// Sécurité logique : on arrête uniquement l'automatisme. Commandes manuelles possibles.
flow.set('arrosage_state', 'IDLE');
flow.set('arrosage_debut', null);
flow.set('arrosage_duree_ms', 0);
flow.set('pending_config_lent', false);

// Historique central
let logs = flow.get("global_event_logs") || [];
const t = new Date().toLocaleTimeString('fr-FR', {timeZone: (cfg.timezone || "Europe/Paris"), hour:'2-digit', minute:'2-digit', second:'2-digit'});
logs.unshift({ time: t, msg: reason, type: "error", icon: "⚠️" });
if (logs.length > 50) logs = logs.slice(0, 50);
flow.set("global_event_logs", logs);

node.error(`[WATCHDOG VANNE] ${reason}`);
msg.payload = {
    action: "ERREUR VANNE",
    raison: reason,
    duree: 0,
    deficit: null,
    methode: "timeout-lorawan",
    confiance: 0,
    age_capteur_min: null,
    age_meteo_min: null
};
return msg;

// PROFIL PLANTE v5 — sélection dashboard
// Ajuste les seuils d'humidité, le délai entre arrosages et les limites jour.

let cfg = flow.get("config_jardin") || {};
const profiles = cfg.plantProfiles || {};
let key = flow.get("active_plant_profile_key") || cfg.activePlantProfile || "permaculture_mix";

if (msg.topic === "set_plant_profile") {
    const requested = msg.payload?.profile || msg.payload;
    if (profiles[requested]) {
        key = requested;
        flow.set("active_plant_profile_key", key);
        cfg.activePlantProfile = key;
        flow.set("config_jardin", cfg);
        node.warn(`[PROFIL PLANTE] Profil actif : ${profiles[key].label || key}`);
    } else {
        node.warn(`[PROFIL PLANTE] Profil inconnu : ${requested}`);
    }
}

const profile = profiles[key] || profiles.permaculture_mix || {};
const state = {
    plant_profile_key: key,
    plant_profile: profile,
    plant_profile_label: profile.label || key,
    available_profiles: profiles,
    irrigation_type: cfg.irrigationType || "souterrain",
    sensor_observation_delay_min: cfg.sensorObservationDelayMin || 180,
    sensor_scale_mode: cfg.sensorScaleMode || "calibre_bas_25pct",
    sensor_wet_max_pct: cfg.sensorWetMaxPct || 25,
    trigger_pct: profile.triggerPct,
    target_pct: profile.targetPct,
    max_pct: profile.maxPct,
    min_hours_between_watering: profile.minHoursBetweenWatering || cfg.minHoursBetweenWatering,
    max_auto_waterings_day: profile.maxAutoWateringsPerDay || cfg.maxAutoWateringsPerDay,
    max_irrigation_min: profile.maxIrrigationMin || cfg.maxIrrigationMin
};

flow.set("plant_profile_state", {
    key,
    profile,
    irrigation_type: state.irrigation_type,
    sensor_observation_delay_min: state.sensor_observation_delay_min,
    sensor_scale_mode: state.sensor_scale_mode,
    sensor_wet_max_pct: state.sensor_wet_max_pct
});

msg.topic = "plant_profile_state";
msg.payload = state;
return msg;

// COUPURE ÉNERGIE ECOFLOW — applique la sécurité côté flow arrosage
// Entrée : évènements ENERGY_CUTOFF_ENTER / ENERGY_RESUME du tab EcoFlow.
// Sortie 1 : ordre fermeture vanne LYVA
// Sortie 2 : log dashboard
// Sortie 3 : commande pompe OFF à raccorder si une sortie pompe existe

const cfg = Object.assign({
    valveDevice: "lyva-tre",
    closeHex: "02"
}, flow.get("config_jardin") || {});

const evt = msg.payload || {};
const event = evt.event || "ENERGY_CUTOFF_ENTER";
const soc = evt.soc ?? global.get("ecoflow_soc");
const reason = evt.reason || global.get("energy_cutoff_reason") || "Coupure énergie EcoFlow";

// Sécurité désactivable : en OFF on ignore les coupures (les reprises restent traitées)
if (global.get("ecoflow_guard") !== true && event !== "ENERGY_RESUME") {
    node.warn("[ECOFLOW] " + event + " ignoré — sécurité EcoFlow désactivée (Réglages)");
    return null;
}

flow.set("energy_cutoff_state", {
    active: global.get("energy_cutoff") === true,
    soc,
    reason,
    event,
    timestamp: Date.now()
});

if (event === "ENERGY_RESUME") {
    flow.set("energy_cutoff_active", false);
    flow.set("arrosage_state", "IDLE");
    flow.set("pending_config_lent", false);

    // Réarmement AUTO si la coupure l'avait désactivé
    let autoMsg = null;
    if (flow.get("auto_before_cutoff") === true) {
        flow.set("auto_active", true);
        flow.set("auto_before_cutoff", null);
        autoMsg = { topic: "auto_state", payload: true, auto_active: true };
        node.warn("[ECOFLOW] AUTO réactivé automatiquement après reprise énergie");
    }

    const logMsg = {
        topic: "energy",
        payload: {
            event: "ENERGY_RESUME",
            soc,
            message: `EcoFlow rechargée (${soc}%) — arrosage de nouveau autorisable`,
            type: "success"
        }
    };

    node.warn(`[ECOFLOW] Reprise autorisée — SOC ${soc}%`);
    return [null, logMsg, null, autoMsg];
}

// Coupure énergie : arrêt complet de la logique arrosage
// On mémorise l'état AUTO pour réarmement à la reprise
if (flow.get("auto_active") === true) flow.set("auto_before_cutoff", true);
flow.set("energy_cutoff_active", true);
flow.set("auto_active", false);
flow.set("arrosage_state", "IDLE");
flow.set("arrosage_debut", null);
flow.set("arrosage_duree_ms", 0);
flow.set("pending_config_lent", false);
flow.set("attente_mesure_post", null);

// Nettoyage état pending vanne
let vs = flow.get("valve_state") || {};
vs.pending_command = null;
vs.pending_state = null;
vs.pending_since_ts = null;
vs.error = reason;
flow.set("valve_state", vs);

// Fermeture vanne : on laisse passer même en coupure énergie
const closeMsg = {
    topic: "valve",
    origin: "energy_cutoff",
    payload: {
        device_id: cfg.valveDevice,
        command: cfg.closeHex,
        origin: "energy_cutoff",
        reason
    }
};

// Log pour dashboard
const logMsg = {
    topic: "energy",
    payload: {
        event: "ENERGY_CUTOFF_ENTER",
        soc,
        message: `Coupure énergie EcoFlow (${soc}%) — AUTO OFF, fermeture vanne, pompe OFF à raccorder`,
        type: "error"
    }
};

// Sortie pompe OFF à raccorder si tu ajoutes un relais, une prise connectée,
// ou une commande EcoFlow setQuota validée pour couper la sortie AC/DC.
const pumpMsg = {
    topic: "pump",
    payload: {
        command: "OFF",
        soc,
        reason,
        note: "À raccorder à la commande réelle de pompe : relais, prise connectée, MQTT, API EcoFlow AC/DC, etc."
    }
};

node.warn(`[ECOFLOW] COUPURE — ${reason} — AUTO OFF + fermeture vanne`);
return [closeMsg, logMsg, pumpMsg, null];

format:
/* ===== Dashboard Ocean — Jardin permaculture =====
   Implémentation du design claude.ai « Dashboard Ocean.dc.html ».
   Chaque page est un template plein écran ; ces classes oc-* portent tout le design. */
@import url('https://fonts.googleapis.com/css2?family=Lora:wght@500;600&display=swap');

:root {
    --j-accent: #5fc4a8;
    --j-accent-2: #f0a35e;
    --j-warn: #f0a35e;
    --j-error: #ff5252;
    --j-text: #e9f3f2;
    --j-text-2: #8ba7a6;
    --j-bg: #0f1e20;
    --j-card-bg: #17292c;
    --j-card-border: #2c4448;
    --j-radius: 22px;
}

body, .v-application {
    font-family: 'Avenir Next', 'Segoe UI', system-ui, sans-serif !important;
    background: #0f1e20 !important;
}

/* Le design fournit sa propre entête + navigation : on masque le chrome Dashboard 2.0 */
.v-app-bar, .v-navigation-drawer { display: none !important; }
.v-main { padding: 0 !important; }
.nrdb-ui-group > .v-card { background: transparent !important; border: none !important; box-shadow: none !important; }

a { color: #f0a35e; }
a:hover { color: #f5b57c; }
.nrdb-ui-template ::-webkit-scrollbar { width: 8px; height: 8px; }
.nrdb-ui-template ::-webkit-scrollbar-thumb { background: #2c4448; border-radius: 4px; }
.nrdb-ui-template ::-webkit-scrollbar-track { background: transparent; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

/* ---- squelette de page ---- */
.oc-wrap { width: 100%; max-width: 1080px; margin: 0 auto; padding: 20px 16px 48px; color: #e9f3f2; }
.oc-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 14px; flex-wrap: wrap; gap: 8px; }
.oc-brand { font-family: 'Lora', Georgia, serif; font-size: 22px; }
.oc-meta { font-size: 12px; color: #8ba7a6; }
.oc-serif { font-family: 'Lora', Georgia, serif; }
.oc-mut { color: #8ba7a6; }
.oc-sub { font-size: 12px; color: #8ba7a6; }
.oc-title { font-family: 'Lora', Georgia, serif; font-size: 19px; margin-bottom: 12px; }

/* ---- navigation pilule ---- */
.oc-nav { display: flex; gap: 6px; background: #17292c; border: 1px solid #2c4448; border-radius: 999px; padding: 6px; margin-bottom: 16px; }
.oc-nav button { flex: 1; text-align: center; padding: 10px 0; border-radius: 999px; border: none; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 600; background: transparent; color: #8ba7a6; transition: background .2s, color .2s; }
.oc-nav button:hover { background: rgba(95, 196, 168, .12); color: #e9f3f2; }
.oc-nav button.on { background: #5fc4a8; color: #0f1e20; }
@media (max-width: 640px) { .oc-nav-lbl { display: none; } .oc-nav button { font-size: 16px; } }

/* ---- bandeaux ---- */
.oc-banner { border-radius: 16px; padding: 10px 14px; margin-bottom: 12px; font-size: 13px; }
.oc-banner.terra { background: rgba(240, 163, 94, .14); border: 1px solid #f0a35e; color: #f0a35e; }
.oc-banner.mut { background: rgba(164, 145, 122, .12); border: 1px solid #8ba7a6; color: #8ba7a6; }
.oc-banner.err { background: rgba(255, 82, 82, .12); border: 1px solid #ff5252; color: #ff8a8a; }

/* ---- cartes & tuiles ---- */
.oc-card { background: #17292c; border: 1px solid #2c4448; border-radius: 22px; }
.oc-card.top-sage { border-top: 3px solid #5fc4a8; }
.oc-card.top-terra { border-top: 3px solid #f0a35e; }
.oc-col { padding: 20px; display: flex; flex-direction: column; align-items: center; gap: 12px; }
.oc-grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 10px; margin-bottom: 10px; }
.oc-cardhead { align-self: flex-start; display: flex; align-items: center; justify-content: space-between; width: 100%; gap: 8px; flex-wrap: wrap; }
.oc-badge { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: .08em; }
.oc-badge.sage { background: rgba(95, 196, 168, .14); border: 1px solid #5fc4a8; color: #5fc4a8; }
.oc-badge.terra { background: rgba(240, 163, 94, .14); border: 1px solid #f0a35e; color: #f0a35e; }
.oc-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 10px; }
.oc-tile { background: #17292c; border: 1px solid #2c4448; border-radius: 18px; padding: 14px; }
.oc-tile-in { background: #0f1e20; border: 1px solid #2c4448; border-radius: 16px; padding: 11px; }
.oc-lbl { font-size: 11px; color: #8ba7a6; margin-bottom: 4px; }
.oc-lbl2 { font-size: 10px; color: #8ba7a6; margin-bottom: 3px; }
.oc-val { font-size: 17px; font-weight: 600; }
.oc-val.sage { color: #5fc4a8; }
.oc-statgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 8px; }

/* ---- carte capteur ---- */
.oc-gauge { width: 124px; height: 124px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #1e3236, #17292c); border: 3px solid #5fc4a8; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.oc-gauge-val { font-family: 'Lora', Georgia, serif; font-size: 34px; color: #5fc4a8; }
.oc-gauge-lbl { font-size: 11px; color: #8ba7a6; }
.oc-inline { display: flex; gap: 20px; font-size: 13px; flex-wrap: wrap; justify-content: center; }
.oc-bars { width: 100%; display: flex; flex-direction: column; gap: 10px; }
.oc-barlbl { font-size: 11px; color: #8ba7a6; margin-bottom: 5px; display: flex; justify-content: space-between; }
.oc-bartrack { height: 10px; background: #0f1e20; border-radius: 999px; overflow: hidden; border: 1px solid #2c4448; }
.oc-barfill { height: 100%; background: linear-gradient(90deg, #5fc4a8, #f0a35e); transition: width .4s; }
.oc-barfill.grey { background: #2c4448; border-right: 2px solid #8ba7a6; }

/* ---- carte actionneur ---- */
.oc-valvezone { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; width: 100%; }
.oc-valve { width: 118px; height: 118px; border-radius: 50% 46% 52% 48% / 48% 52% 46% 52%; border: none; background: #5fc4a8; color: #0f1e20; font-size: 16px; font-weight: 700; cursor: pointer; box-shadow: inset 0 -6px 12px rgba(0, 0, 0, .25), 0 8px 20px rgba(0, 0, 0, .35); font-family: inherit; transition: background .2s; }
.oc-valve.open { background: #f0a35e; }
.oc-valve.pending { background: #8a6b3f; color: #e9f3f2; }
.oc-valve.locked { cursor: not-allowed; opacity: .75; }
.oc-refresh { cursor: pointer; color: #8ba7a6; margin-left: 4px; text-decoration: none; }
.oc-refresh:hover { color: #5fc4a8; }
.oc-ctrls { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; justify-content: center; }
.oc-autopill { display: flex; align-items: center; gap: 8px; padding: 8px 12px; background: #0f1e20; border: 1px solid #2c4448; border-radius: 999px; }
.oc-tgl { width: 42px; height: 24px; border-radius: 999px; background: #2c4448; cursor: pointer; position: relative; transition: background .2s; flex: none; }
.oc-tgl .knob { position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #ffffff; transition: transform .2s; }
.oc-tgl.on { background: #5fc4a8; }
.oc-tgl.on .knob { transform: translateX(18px); }
.oc-tgl.warn.on { background: #f0a35e; }
.oc-seg { display: flex; background: #0f1e20; border: 1px solid #2c4448; border-radius: 999px; padding: 3px; gap: 2px; }
.oc-seg button { border: none; border-radius: 999px; padding: 5px 12px; font-size: 12px; cursor: pointer; background: transparent; color: #8ba7a6; font-family: inherit; }
.oc-seg button.on { background: #5fc4a8; color: #0f1e20; }
.oc-seg button:disabled { cursor: not-allowed; opacity: .6; }

/* ---- journal ---- */
.oc-log { display: flex; flex-direction: column; gap: 8px; font-size: 13px; }
.oc-logrow { display: flex; gap: 12px; align-items: baseline; }
.oc-logtime { color: #f0a35e; font-variant-numeric: tabular-nums; flex: none; }

/* ---- météo ---- */
.oc-hero { background: linear-gradient(160deg, #234039 0%, #17292c 70%); border: 1px solid #2c4448; border-radius: 22px; padding: 26px 24px; margin-bottom: 10px; }
.oc-hours { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 6px; }
.oc-hour { flex: none; width: 64px; display: flex; flex-direction: column; align-items: center; gap: 6px; background: #0f1e20; border: 1px solid #2c4448; border-radius: 16px; padding: 10px 0; }
.oc-dayrow { display: grid; grid-template-columns: 56px 24px 34px 1fr 34px; gap: 10px; align-items: center; font-size: 13px; }
.oc-daytrack { height: 8px; background: #0f1e20; border-radius: 999px; border: 1px solid #2c4448; position: relative; }
.oc-dayfill { position: absolute; top: 0; bottom: 0; background: linear-gradient(90deg, #5fc4a8, #f0a35e); border-radius: 999px; }
.oc-tiles.small .oc-val { font-size: 15px; }

/* ---- IA ---- */
.oc-decision { border-radius: 999px; padding: 8px 18px; font-size: 14px; font-weight: 700; letter-spacing: .08em; }
.oc-ghostbtn { border: 1px solid #8ba7a6; background: transparent; color: #8ba7a6; border-radius: 999px; padding: 5px 12px; font-size: 12px; cursor: pointer; font-family: inherit; }
.oc-ghostbtn.dark { border-color: #2c4448; background: #0f1e20; padding: 4px 12px; }
.oc-ghostbtn:hover { color: #e9f3f2; border-color: #5fc4a8; }
.oc-iarow { display: grid; grid-template-columns: 110px 110px 1fr 80px; gap: 10px; font-size: 13px; padding: 9px 0; border-bottom: 1px solid #23383c; align-items: baseline; }
.oc-iarow.head { font-size: 11px; color: #8ba7a6; padding: 0 0 8px; border-bottom: 1px solid #2c4448; }
.oc-iarow:last-child { border-bottom: none; }

/* ---- EcoFlow ---- */
.oc-ring { width: 172px; height: 172px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 8px 24px rgba(0, 0, 0, .35); }
.oc-ring-in { width: 138px; height: 138px; border-radius: 50%; background: #17292c; border: 1px solid #2c4448; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.oc-statgrid.wide { grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
.oc-dot { width: 9px; height: 9px; border-radius: 50%; background: #5fc4a8; box-shadow: 0 0 8px #5fc4a8; flex: none; }
.oc-dot.off { background: #ff5252; box-shadow: 0 0 8px #ff5252; }
.oc-alert { border: 1px solid #2c4448; border-radius: 16px; padding: 12px 14px; font-size: 13px; }

/* ---- Réglages ---- */
.oc-chips { display: flex; flex-wrap: wrap; background: #0f1e20; border: 1px solid #2c4448; border-radius: 24px; padding: 4px; gap: 2px; margin: 0 auto 14px; max-width: 720px; width: 100%; }
.oc-chip { flex: 1 1 30%; border: none; border-radius: 999px; padding: 8px 6px; font-size: 13px; cursor: pointer; background: transparent; color: #8ba7a6; font-family: inherit; font-weight: 600; white-space: nowrap; }
.oc-chip.on { background: #5fc4a8; color: #0f1e20; }
.oc-setgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 10px; margin-bottom: 10px; }
.oc-setcard { background: #17292c; border: 1px solid #2c4448; border-radius: 22px; padding: 16px 18px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 10px; transition: border-color .2s; }
.oc-setcard:hover { border-color: #5fc4a8; }
.oc-chev { color: #8ba7a6; font-size: 18px; }
.oc-overlay { position: fixed; inset: 0; background: rgba(12, 9, 6, .72); z-index: 50; display: flex; align-items: center; justify-content: center; padding: 20px; }
.oc-modal { background: #17292c; border: 1px solid #2c4448; border-radius: 22px; padding: 20px; width: min(500px, 100%); max-height: 85vh; overflow-y: auto; box-shadow: 0 24px 60px rgba(0, 0, 0, .6); }
.oc-modalhead { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.oc-close { width: 30px; height: 30px; border-radius: 50%; border: 1px solid #2c4448; background: #0f1e20; color: #8ba7a6; cursor: pointer; font-family: inherit; }
.oc-setrow { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 11px 0; border-bottom: 1px solid #23383c; flex-wrap: wrap; }
.oc-setrow.last { border-bottom: none; }

/* Les pages Ocean définissent leur propre hauteur : le widget s'étend librement */
.nrdb-ui-template, .nrdb-layout-group--grid { height: auto !important; min-height: 0 !important; }
.nrdb-ui-template { overflow: visible !important; }

func:
// ÉTAT SYSTÈME — agrège l'état réel pour la carte de synthèse (page Jardin).
// Déclenché par : tick 30 s, ouverture de page, et événements clés (vanne,
// coupure énergie, débitmètre, AUTO, maintenance). Le contenu du msg entrant
// est ignoré : tout est relu depuis le contexte.
const vs = flow.get('valve_state') || {};
const quota = flow.get('water_quota_state') || {};
const soc = Number(global.get('ecoflow_soc'));
const cutoff = global.get('energy_cutoff') === true || global.get('energie_ok') === false;
const ecoLast = global.get('ecoflow_last_seen') || global.get('ecoflow_last_update');
const lastIA = (global.get('ia_command_log') || [])[0] || null;
const capteur = flow.get('capteur_sol_data') || {};

msg.payload = {
    valve_state: vs.confirmed_state || 'Inconnu',
    valve_pending: vs.pending_state || null,
    valve_battery: vs.battery ?? null,
    arrosage_state: flow.get('arrosage_state') || 'IDLE',
    auto: flow.get('auto_active') === true,
    maintenance: flow.get('maintenance_active') === true,
    soc: Number.isFinite(soc) ? Math.round(soc) : null,
    energy_cutoff: cutoff,
    ecoflow_guard: global.get('ecoflow_guard') === true,
    hum: capteur.humidity ?? null,
    temp: capteur.temperature ?? null,
    capteur_battery: capteur.battery ?? null,
    vanne_mode: flow.get('vanne_current_mode') || null,
    energy_reason: global.get('energy_cutoff_reason') || null,
    eco_age_min: ecoLast ? Math.round((Date.now() - Number(ecoLast)) / 60000) : null,
    water_remaining: quota.remaining ?? null,
    water_quota: quota.quota ?? null,
    water_consumed: quota.consumed ?? null,
    ia_type: lastIA ? lastIA.type : null,
    ia_heure: lastIA ? lastIA.heure : null,
    ia_raison: lastIA ? lastIA.raison : null,
    ts: Date.now()
};
msg.topic = 'etat_systeme';
return msg;

// Coordonnées de Saint-Quentin-Fallavier
const LAT = 45.6313;
const LON = 5.1137;

msg.location = {
    name: "St-Quentin-Fallavier",
    lat: LAT,
    lon: LON
};

// URL Météo (Open-Meteo)
msg.url = `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}` +
    `&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,rain,weather_code,cloud_cover,pressure_msl,surface_pressure,wind_speed_10m,wind_direction_10m` +
    `&hourly=temperature_2m,precipitation_probability,weather_code,uv_index` +
    `&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,uv_index_max,precipitation_sum,precipitation_probability_max` +
    `&timezone=auto&forecast_days=10`;

return msg;

if(msg.statusCode !== 200) return null;
msg.weatherData = msg.payload;

const lat = msg.location.lat;
const lon = msg.location.lon;

msg.url = `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${lat}&longitude=${lon}&current=european_aqi&timezone=auto`;
return msg;

// L'AQI n'est pas bloquant : si l'appel qualité de l'air a échoué,
// on affiche quand même la météo (tuile air en "--").
const aqiOk = msg.statusCode === 200 && msg.payload && msg.payload.current;
const air = aqiOk ? msg.payload : null;

const loc = msg.location;
const w = msg.weatherData;
if (!loc || !w || !w.current || !w.hourly || !w.daily) return null;
const current = w.current;
const hourly = w.hourly;
const daily = w.daily;

// --- HELPERS ---
const getIcon = (code) => {
    const map = {
        0: 'mdi-weather-sunny', 1: 'mdi-weather-partly-cloudy', 2: 'mdi-weather-partly-cloudy', 3: 'mdi-weather-cloudy',
        45: 'mdi-weather-fog', 48: 'mdi-weather-fog',
        51: 'mdi-weather-rainy', 53: 'mdi-weather-rainy', 55: 'mdi-weather-pouring',
        61: 'mdi-weather-rainy', 63: 'mdi-weather-pouring', 65: 'mdi-weather-pouring',
        71: 'mdi-weather-snowy', 73: 'mdi-weather-snowy', 75: 'mdi-weather-snowy-heavy',
        80: 'mdi-weather-pouring', 81: 'mdi-weather-pouring', 82: 'mdi-weather-pouring',
        95: 'mdi-weather-lightning', 96: 'mdi-weather-lightning-rainy', 99: 'mdi-weather-lightning-rainy'
    };
    if (current.is_day === 0 && code <= 2) return map[code].replace('sunny', 'night').replace('partly-cloudy', 'night-partly-cloudy');
    return map[code] || 'mdi-weather-cloudy';
};

const formatTime = (isoStr) => isoStr.split('T')[1].substring(0, 5);

// --- HEADER ---
const header = {
    city: loc.name,
    temp: Math.round(current.temperature_2m),
    high: Math.round(daily.temperature_2m_max[0]),
    low: Math.round(daily.temperature_2m_min[0]),
    feels_like: Math.round(current.apparent_temperature)
};

// --- HOURLY ---
let nowIndex = 0;
const currentHourIso = current.time.substring(0, 13);
for (let i = 0; i < hourly.time.length; i++) {
    if (hourly.time[i].startsWith(currentHourIso)) { nowIndex = i; break; }
}
const hourlyList = [];
for (let i = nowIndex; i < nowIndex + 24; i++) {
    if (!hourly.time[i]) break;
    hourlyList.push({
        time: hourly.time[i].split('T')[1].substring(0, 2) + ' h',
        icon: getIcon(hourly.weather_code[i]),
        temp: Math.round(hourly.temperature_2m[i]),
        pop: hourly.precipitation_probability[i]
    });
}
if (hourlyList.length > 0) hourlyList[0].time = "Maint.";

// --- DAILY ---
const dailyList = [];
const days = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam'];
for (let i = 0; i < daily.time.length; i++) {
    let d = new Date(daily.time[i]);
    let dayName = days[d.getDay()];
    if (i === 0) dayName = "Auj.";
    dailyList.push({
        day: dayName,
        icon: getIcon(daily.weather_code[i]),
        min: Math.round(daily.temperature_2m_min[i]),
        max: Math.round(daily.temperature_2m_max[i]),
        barStart: Math.max(0, (daily.temperature_2m_min[i] + 10) * 2),
        barWidth: Math.max(5, (daily.temperature_2m_max[i] - daily.temperature_2m_min[i]) * 2)
    });
}

// --- TILES ---
let aqiRaw = (air && air.current && air.current.european_aqi !== undefined) ? air.current.european_aqi : null;
let aqiText = "Bonne", aqiColor = "#4caf50";
if (aqiRaw === null) { aqiRaw = "--"; aqiText = "Indispo."; aqiColor = "#9e9e9e"; }
else {
    if (aqiRaw > 20) { aqiText = "Moyenne"; aqiColor = "#ffeb3b"; }
    if (aqiRaw > 40) { aqiText = "Mauvaise"; aqiColor = "#f44336"; }
    if (aqiRaw > 60) { aqiText = "Dangereuse"; aqiColor = "#b71c1c"; }
}

// --- BACKGROUND APPLE ---
const getAppleBackground = (code, isDay) => {
    if (isDay === 0) {
        if (code >= 95) return 'linear-gradient(to bottom, #23202a, #131219)';
        if (code >= 71 && code <= 77) return 'linear-gradient(to bottom, #232d3d, #12171f)';
        return 'linear-gradient(to bottom, #0f1724, #1c2738)';
    }
    if (code >= 95) return 'linear-gradient(to bottom, #3E4651, #21252e)';
    if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82)) return 'linear-gradient(to bottom, #586879, #333F4E)';
    if ((code >= 71 && code <= 77) || code >= 85) return 'linear-gradient(to bottom, #9abfd9, #607D9B)';
    if (code === 45 || code === 48) return 'linear-gradient(to bottom, #8E9BA6, #606E79)';
    if (code === 3) return 'linear-gradient(to bottom, #7a8999, #546475)';
    if (code === 1 || code === 2) return 'linear-gradient(to bottom, #6FA6D6, #4278A6)';
    return 'linear-gradient(to bottom, #5CA0F2, #3068BF)';
};

const details = {
    air: { val: aqiRaw, text: aqiText, color: aqiColor },
    wind: { speed: Math.round(current.wind_speed_10m), deg: current.wind_direction_10m },
    uv: Math.round(hourly.uv_index[nowIndex] || 0),
    uv_max: Math.round(daily.uv_index_max[0]),
    sunset: formatTime(daily.sunset[0]),
    sunrise: formatTime(daily.sunrise[0]),

    // ICI : ON PREND LE CUMUL JOURNALIER AU LIEU DE L'INSTANTANÉ
    rain: daily.precipitation_sum[0],

    hum: current.relative_humidity_2m,
    radarLat: loc.lat, radarLon: loc.lon
};

const bg = getAppleBackground(current.weather_code, current.is_day);

msg.payload = { header, hourly: hourlyList, daily: dailyList, details, bg };
return msg;

// On sauvegarde les données météo dans une mémoire accessible PARTOUT
// Ajout v2 : timestamp indispensable pour que l'IA refuse une météo périmée.
if (!msg.payload) return null;

msg.payload.timestamp = Date.now();
msg.payload.updatedAtTs = msg.payload.timestamp;
msg.payload.updatedAt = new Date().toISOString();

global.set("meteo_live", msg.payload);

// On ne propage pas : le widget UI est alimenté directement par le nœud précédent
return null;

// ECOFLOW → energie_ok + coupure énergie
// Règle :
// - SOC <= 10 %  : coupure énergie, AUTO OFF, fermeture vanne demandée
// - SOC >= 25 %  : reprise autorisée
// - entre 10 et 25 % : conserve l'état précédent

const CUTOFF_SOC = 10;
const RESUME_SOC = 25;

let data = msg.payload || {};
const now = Date.now();

// L'API a répondu : l'appareil est joignable, même si les valeurs sont figées.
// ecoflow_last_seen = dernière réponse API OK (base du watchdog offline).
global.set("ecoflow_last_seen", now);

// --- Détection de fraîcheur ---
// L'API cloud EcoFlow répond même quand l'appareil ne pousse plus de données :
// elle renvoie alors les DERNIÈRES valeurs connues (figées). On ne considère la
// donnée "fraîche" que si le payload a réellement changé depuis la lecture
// précédente. ecoflow_last_update = date du dernier CHANGEMENT de données.
const fingerprint = JSON.stringify(data);
const dataChanged = fingerprint !== context.get("ecoflow_fingerprint");
if (dataChanged) {
    context.set("ecoflow_fingerprint", fingerprint);
    global.set("ecoflow_last_update", now);
}
const lastChange = global.get("ecoflow_last_update") || 0;
const frozenMin = lastChange ? (now - lastChange) / 60000 : null;

// SOC batterie EcoFlow
let soc = Number(
    data["bms_emsStatus.f32LcdShowSoc"] ??
    data["bms_bmsStatus.f32ShowSoc"] ??
    data["pd.soc"] ??
    data["bms_bmsStatus.soc"]
);

// Puissance entrée / sortie
let wattsIn = Number(
    data["pd.wattsInSum"] ??
    data["inv.inputWatts"] ??
    data["bms_bmsStatus.inputWatts"] ??
    data["mppt.inWatts"] ??
    0
);

let wattsOut = Number(
    data["pd.wattsOutSum"] ??
    data["inv.outputWatts"] ??
    data["bms_bmsStatus.outputWatts"] ??
    data["pd.invOutWatts"] ??
    0
);

// Temps restant
let remainTime = Number(
    data["pd.remainTime"] ??
    data["bms_emsStatus.dsgRemainTime"] ??
    data["bms_emsStatus.chgRemainTime"] ??
    0
);

// État général
let acEnabled = Number(data["inv.cfgAcEnabled"] ?? 0);
let dcOutState = Number(data["pd.dcOutState"] ?? 0);
let wifiRssi = Number(data["pd.wifiRssi"] ?? 0);
let soh = Number(
    data["bms_bmsInfo.soh"] ??
    data["bms_bmsStatus.soh"] ??
    0
);

let previousCutoff = global.get("energy_cutoff") === true;
let wasOffline = global.get("ecoflow_online") === false;

// Données figées + déjà hors ligne (watchdog/catch) : ne surtout pas re-marquer
// "en ligne". On alimente seulement le dashboard avec les dernières valeurs connues.
if (!dataChanged && wasOffline) {
    return [{
        payload: {
            ecoflow_online: false,
            stale: true,
            soc: isNaN(soc) ? null : Math.round(soc * 10) / 10,
            wattsIn, wattsOut, remainTime, acEnabled, dcOutState, soh, wifiRssi,
            data_age_min: frozenMin === null ? null : Math.round(frozenMin),
            last_update_ts: lastChange || null,
            energie_ok: false,
            energy_cutoff: true,
            cutoff_soc: CUTOFF_SOC,
            resume_soc: RESUME_SOC,
            reason: global.get("energy_cutoff_reason") || "Données EcoFlow figées",
            status: "HORS LIGNE - données figées (dernières valeurs connues)"
        }
    }, null, null];
}

// Sécurité lecture SOC
if (isNaN(soc) || soc < 0 || soc > 100) {
    global.set("ecoflow_online", false);
    global.set("energie_ok", false);
    global.set("energy_cutoff", true);
    global.set("energy_cutoff_reason", "SOC EcoFlow invalide ou absent");

    const statusMsg = {
        payload: {
            api_ok: true,
            ecoflow_online: false,
            energie_ok: false,
            energy_cutoff: true,
            cutoff_soc: CUTOFF_SOC,
            resume_soc: RESUME_SOC,
            last_update_ts: Date.now(),
            erreur: "SOC EcoFlow invalide ou absent",
            soc_recu: soc,
            status: "Sécurité énergie active - SOC EcoFlow invalide"
        }
    };

    const eventMsg = previousCutoff ? null : {
        topic: "energy_cutoff",
        payload: {
            event: "ENERGY_CUTOFF_ENTER",
            reason: "SOC EcoFlow invalide ou absent",
            soc: null,
            cutoff_soc: CUTOFF_SOC,
            resume_soc: RESUME_SOC,
            ts: Date.now()
        }
    };

    node.warn("SOC EcoFlow invalide ou absent — sécurité énergie active");
    return [statusMsg, eventMsg, null];
}

// Hystérésis : coupure sous 10 %, reprise à partir de 25 %
let energyCutoff = previousCutoff;
let reason = global.get("energy_cutoff_reason") || null;

if (soc <= CUTOFF_SOC) {
    energyCutoff = true;
    reason = `Batterie EcoFlow critique (${Math.round(soc * 10) / 10}% <= ${CUTOFF_SOC}%)`;
}

if (soc >= RESUME_SOC) {
    energyCutoff = false;
    reason = null;
}

let energie_ok = !energyCutoff;

// Variables globales pour tout le flow irrigation
global.set("ecoflow_online", true);
global.set("ecoflow_soc", soc);
global.set("ecoflow_watts_in", wattsIn);
global.set("ecoflow_watts_out", wattsOut);
global.set("ecoflow_remain_time", remainTime);
global.set("ecoflow_ac_enabled", acEnabled);
global.set("ecoflow_dc_out_state", dcOutState);
global.set("ecoflow_wifi_rssi", wifiRssi);
global.set("ecoflow_soh", soh);
global.set("energie_ok", energie_ok);
global.set("energy_cutoff", energyCutoff);
global.set("energy_cutoff_reason", reason);
global.set("energy_cutoff_soc", CUTOFF_SOC);
global.set("energy_resume_soc", RESUME_SOC);

let connectivityMsg = null;
if (wasOffline) {
    connectivityMsg = {
        topic: "ecoflow_connectivity",
        payload: {
            event: "ECOFLOW_ONLINE",
            reason: `Connexion EcoFlow rétablie (SOC ${Math.round(soc * 10) / 10}%)`,
            ts: Date.now()
        }
    };
    node.warn("[ECOFLOW] Connexion rétablie");
}

let statusMsg = {
    payload: {
        ecoflow_online: true,
        soc: Math.round(soc * 10) / 10,
        wattsIn: wattsIn,
        wattsOut: wattsOut,
        remainTime: remainTime,
        acEnabled: acEnabled,
        dcOutState: dcOutState,
        soh: soh,
        wifiRssi: wifiRssi,
        stale: !dataChanged && frozenMin !== null && frozenMin > 10,
        data_age_min: frozenMin === null ? null : Math.round(frozenMin),
        last_update_ts: lastChange,
        energie_ok: energie_ok,
        energy_cutoff: energyCutoff,
        cutoff_soc: CUTOFF_SOC,
        resume_soc: RESUME_SOC,
        reason: reason,
        status: energyCutoff
            ? "COUPURE ÉNERGIE - arrosage bloqué, attente recharge"
            : "Énergie OK - arrosage autorisé"
    }
};

// Évènement uniquement au changement d'état
let eventMsg = null;

if (energyCutoff && !previousCutoff) {
    eventMsg = {
        topic: "energy_cutoff",
        payload: {
            event: "ENERGY_CUTOFF_ENTER",
            reason: reason,
            soc: Math.round(soc * 10) / 10,
            wattsIn: wattsIn,
            wattsOut: wattsOut,
            cutoff_soc: CUTOFF_SOC,
            resume_soc: RESUME_SOC,
            ts: Date.now()
        }
    };
    node.warn(`[ECOFLOW] ${reason} — AUTO OFF + fermeture vanne demandée`);
}

if (!energyCutoff && previousCutoff) {
    eventMsg = {
        topic: "energy_cutoff",
        payload: {
            event: "ENERGY_RESUME",
            reason: `Batterie EcoFlow rechargée (${Math.round(soc * 10) / 10}% >= ${RESUME_SOC}%)`,
            soc: Math.round(soc * 10) / 10,
            wattsIn: wattsIn,
            wattsOut: wattsOut,
            cutoff_soc: CUTOFF_SOC,
            resume_soc: RESUME_SOC,
            ts: Date.now()
        }
    };
    node.warn(`[ECOFLOW] Reprise énergie autorisée — SOC ${Math.round(soc * 10) / 10}%`);
}

return [statusMsg, eventMsg, connectivityMsg];

if (global.get("ecoflow_guard") !== true) {
    msg.payload = { autorisation: true, raison: "Sécurité EcoFlow désactivée (Réglages)" };
    return [msg, null];
}

let energie_ok = global.get("energie_ok");
let soc = global.get("ecoflow_soc");
let last = global.get("ecoflow_last_seen") || global.get("ecoflow_last_update");

if (!last) {
    msg.payload = {
        autorisation: false,
        raison: "Ouverture bloquée : aucune donnée EcoFlow"
    };
    return [null, msg];
}

let age = Date.now() - last;

if (age > 15 * 60 * 1000) {
    msg.payload = {
        autorisation: false,
        raison: "Ouverture bloquée : donnée EcoFlow trop ancienne",
        age_minutes: Math.round(age / 60000)
    };
    return [null, msg];
}

if (energie_ok !== true) {
    msg.payload = {
        autorisation: false,
        raison: "Ouverture bloquée : batterie EcoFlow faible ou attente recharge",
        batterie: soc
    };
    return [null, msg];
}

msg.payload = {
    autorisation: true,
    batterie: soc,
    raison: "Ouverture autorisée : énergie OK"
};

return [msg, null];

// Détecte une déconnexion EcoFlow.
// Offline réel = plus aucune réponse API depuis OFFLINE_AFTER_MIN.
// Données figées = toléré jusqu'à FROZEN_AFTER_MIN : une batterie au repos
// (pas de charge, pas de conso) renvoie un payload identique, c'est normal.
const OFFLINE_AFTER_MIN = 12;  // ~2 cycles de lecture manqués (lecture toutes les 5 min)
const FROZEN_AFTER_MIN  = 60;  // payload strictement identique depuis 1h = suspect

const lastSeen   = global.get("ecoflow_last_seen");
const lastChange = global.get("ecoflow_last_update");
const wasOnline  = global.get("ecoflow_online") !== false;

const seenAgeMin   = lastSeen   ? (Date.now() - lastSeen)   / 60000 : null;
const frozenAgeMin = lastChange ? (Date.now() - lastChange) / 60000 : null;

const apiSilent         = seenAgeMin === null || seenAgeMin > OFFLINE_AFTER_MIN;
const dataFrozenTooLong = frozenAgeMin !== null && frozenAgeMin > FROZEN_AFTER_MIN;

if ((apiSilent || dataFrozenTooLong) && wasOnline) {
    const reason = apiSilent
        ? (seenAgeMin !== null
            ? `Aucune réponse API depuis ${Math.round(seenAgeMin)} min`
            : `Aucune donnée reçue depuis le démarrage (> ${OFFLINE_AFTER_MIN} min)`)
        : `Données figées depuis ${Math.round(frozenAgeMin)} min (> ${FROZEN_AFTER_MIN} min)`;

    global.set("ecoflow_online", false);
    global.set("energie_ok", false);
    global.set("energy_cutoff", true);
    global.set("energy_cutoff_reason", "EcoFlow hors ligne : " + reason);

    node.warn("[ECOFLOW] Perte de connexion détectée (watchdog) : " + reason);

    return {
        topic: "ecoflow_connectivity",
        payload: { event: "ECOFLOW_OFFLINE", reason: reason, ts: Date.now() }
    };
}

return null;

// Capture les erreurs de l'appel API EcoFlow : device éteint, hors réseau,
// timeout, identifiants invalides, etc. Détection plus rapide que le watchdog.
const wasOffline = global.get("ecoflow_online") === false;
const errText = (msg.error && msg.error.message) ? msg.error.message : "Erreur inconnue";

global.set("ecoflow_online", false);
global.set("energie_ok", false);
global.set("energy_cutoff", true);
global.set("energy_cutoff_reason", "Erreur API EcoFlow : " + errText);

node.warn("[ECOFLOW] Erreur API : " + errText);

if (wasOffline) return null; // déjà signalé, pas de doublon d'alerte

return {
    topic: "ecoflow_connectivity",
    payload: { event: "ECOFLOW_API_ERROR", reason: errText, ts: Date.now() }
};

// Formate un message d'alerte unique (toast dashboard + email) à partir
// des événements EcoFlow : coupure énergie, reprise, déconnexion, erreur API.
const p = msg.payload || {};
const event = p.event;
if (!event) return null;

const templates = {
    ENERGY_CUTOFF_ENTER: {
        subject: "⚠️ EcoFlow : coupure énergie jardin",
        text: `Coupure énergie déclenchée sur le jardin permaculture. ${p.reason || ""} (SOC: ${p.soc ?? "?"}%). Arrosage automatique désactivé.`,
        level: "red"
    },
    ENERGY_RESUME: {
        subject: "✅ EcoFlow : énergie rétablie",
        text: `Reprise de l'arrosage autorisée. ${p.reason || ""} (SOC: ${p.soc ?? "?"}%).`,
        level: "green"
    },
    ECOFLOW_OFFLINE: {
        subject: "🔴 EcoFlow : déconnecté",
        text: `L'EcoFlow du jardin ne répond plus. ${p.reason || ""}`,
        level: "red"
    },
    ECOFLOW_ONLINE: {
        subject: "🟢 EcoFlow : reconnecté",
        text: `La connexion à l'EcoFlow est rétablie. ${p.reason || ""}`,
        level: "green"
    },
    ECOFLOW_API_ERROR: {
        subject: "🔴 EcoFlow : erreur API",
        text: `Erreur lors de l'appel à l'API EcoFlow (device probablement éteint ou hors réseau). ${p.reason || ""}`,
        level: "red"
    }
};

const tpl = templates[event];
if (!tpl) return null;

// Dashboard 2.0 : ui-notification attend une chaîne dans msg.payload
const toastMsg = {
    payload: `${tpl.subject} — ${tpl.text}`
};

const mailMsg = {
    topic: tpl.subject,
    payload: `${tpl.text}\n\nHorodatage : ${new Date().toLocaleString('fr-FR', { timeZone: "Europe/Paris" })}`
};

return [toastMsg, mailMsg];

// Interrupteur global de la sécurité énergie EcoFlow (page Réglages).
// OFF (défaut) : l'arrosage continue même si l'EcoFlow est hors ligne ou vide.
if (msg.topic === "set_ecoflow_guard") {
    global.set("ecoflow_guard", msg.payload === true);
    node.warn("[ECOFLOW] Sécurité énergie " + (msg.payload === true ? "RÉACTIVÉE" : "DÉSACTIVÉE"));
}
msg.payload = { ecoflow_guard: global.get("ecoflow_guard") === true };
return msg;
